tool_schemas.implementation:
def search_videos(query, region_code=None, channel_id=None, youtube_channel_id=None, published_after=None, published_before=None, order=None, safe_search=None, limit=None, page_token=None, refresh=None, **_extra):
    import json, os, datetime, re, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0248000" if __import__("os").path.isdir("./environment_mix/0248000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            return ("__bad__", _err("VALIDATION_ERROR", f"{field} must be an ISO date-time string"))
        try:
            ss = s.strip()
            if ss.endswith("Z"):
                dt = datetime.datetime.fromisoformat(ss[:-1] + "+00:00")
            else:
                dt = datetime.datetime.fromisoformat(ss)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return ("__bad__", _err("VALIDATION_ERROR", f"{field} must be a valid ISO date-time"))
    def _norm_query(q):
        return " ".join(q.strip().lower().split())

    def _b32_ulid_like(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        import secrets
        return prefix + "".join(secrets.choice(alphabet) for _ in range(16))

    def _next_reset_boundary(dt):
        # next midnight UTC
        d = dt.astimezone(datetime.timezone.utc).date()
        nxt = datetime.datetime(d.year, d.month, d.day, tzinfo=datetime.timezone.utc) + datetime.timedelta(days=1)
        return nxt

    def _select_client():
        clients = _load("api_clients.json")
        # Prefer active clients; allow only if can be charged at least 1 request (units determined later but >=0)
        for c in clients:
            if c.get("status") == "active":
                return c
        return None

    def _update_client_quota(client, units_to_charge):
        # reset if needed
        qra = client.get("quota_reset_at")
        try:
            if isinstance(qra, str):
                if qra.endswith("Z"):
                    qra_dt = datetime.datetime.fromisoformat(qra[:-1] + "+00:00")
                else:
                    qra_dt = datetime.datetime.fromisoformat(qra)
                    if qra_dt.tzinfo is None:
                        qra_dt = qra_dt.replace(tzinfo=datetime.timezone.utc)
                qra_dt = qra_dt.astimezone(datetime.timezone.utc)
            else:
                qra_dt = now
        except ValueError:
            qra_dt = now

        if qra_dt <= now:
            client["requests_used_today"] = 0
            client["youtube_units_used_today"] = 0
            client["quota_reset_at"] = _iso(_next_reset_boundary(now))
        # enforce
        if not isinstance(client.get("quota_daily_requests"), int) or client["quota_daily_requests"] < 0:
            return _err("VALIDATION_ERROR", "Client quota configuration invalid")
        if not isinstance(client.get("quota_daily_youtube_units"), int) or client["quota_daily_youtube_units"] < 0:
            return _err("VALIDATION_ERROR", "Client quota configuration invalid")
        ru = client.get("requests_used_today")
        yu = client.get("youtube_units_used_today")
        if not isinstance(ru, int) or ru < 0 or not isinstance(yu, int) or yu < 0:
            return _err("VALIDATION_ERROR", "Client usage counters invalid")

        if ru + 1 > client["quota_daily_requests"]:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded")
        if yu + units_to_charge > client["quota_daily_youtube_units"]:
            return _err("QUOTA_EXCEEDED", "Daily YouTube units quota exceeded")
        # apply
        client["requests_used_today"] = ru + 1
        client["youtube_units_used_today"] = yu + units_to_charge
        client["updated_at"] = _iso(now)
        return None

    def _log_request(tool_name, client_id, input_params, status, youtube_units_charged=0, cache_hit=False,
                     normalized_query=None, region_code=None, youtube_video_id=None, youtube_channel_id=None,
                     resolved_video_id=None, resolved_channel_id=None, http_status=None, error_code=None, error_message=None,
                     response_payload=None, started_at=None, finished_at=None):
        reqs = _load("tool_requests.json")
        rid = _b32_ulid_like("ytb_req_")
        row = {
            "id": rid,
            "client_id": client_id,
            "tool_name": tool_name,
            "input_params": input_params if isinstance(input_params, dict) else {},
            "normalized_query": normalized_query,
            "region_code": region_code,
            "youtube_video_id": youtube_video_id,
            "youtube_channel_id": youtube_channel_id,
            "resolved_video_id": resolved_video_id,
            "resolved_channel_id": resolved_channel_id,
            "response_payload": response_payload,
            "http_status": http_status,
            "error_code": error_code,
            "error_message": error_message,
            "youtube_units_charged": int(youtube_units_charged or 0),
            "cache_hit": bool(cache_hit),
            "status": status,
            "started_at": started_at,
            "finished_at": finished_at,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        reqs.append(row)
        _save("tool_requests.json", reqs)
        return row

    # Validate inputs
    input_params = {
        "query": query,
        "region_code": region_code,
        "channel_id": channel_id,
        "youtube_channel_id": youtube_channel_id,
        "published_after": published_after,
        "published_before": published_before,
        "order": order,
        "safe_search": safe_search,
        "limit": limit,
        "page_token": page_token,
        "refresh": refresh,
    }

    # ambient auth: pick a usable client
    client = _select_client()
    if not client:
        # no active client exists to serve the call
        dummy_client_id = (_load("api_clients.json")[0].get("id") if _load("api_clients.json") else "unknown")
        _log_request("search_videos", dummy_client_id, input_params, "failed",
                     youtube_units_charged=0, cache_hit=False, normalized_query=None,
                     http_status=401, error_code="UNAUTHORIZED", error_message="No active client available")
        return _err("UNAUTHORIZED", "No active client available")

    # record received immediately
    req_row = _log_request("search_videos", client["id"], input_params, "received",
                           youtube_units_charged=0, cache_hit=False, normalized_query=_norm_query(query) if isinstance(query, str) else None,
                           region_code=region_code, youtube_channel_id=youtube_channel_id, resolved_channel_id=channel_id)

    # Validate now, but still log failed with 400 if invalid
    if not isinstance(query, str) or not query.strip():
        # transition to failed
        tool_reqs = _load("tool_requests.json")
        for r in tool_reqs:
            if r.get("id") == req_row["id"]:
                r["status"] = "failed"
                r["http_status"] = 400
                r["error_code"] = "VALIDATION_ERROR"
                r["error_message"] = "query is required"
                r["finished_at"] = _iso(now)
                r["updated_at"] = _iso(now)
                break
        _save("tool_requests.json", tool_reqs)
        return _err("VALIDATION_ERROR", "query is required")

    if region_code is not None:
        if not isinstance(region_code, str) or len(region_code) != 2:
            tool_reqs = _load("tool_requests.json")
            for r in tool_reqs:
                if r.get("id") == req_row["id"]:
                    r["status"] = "failed"; r["http_status"] = 400
                    r["error_code"] = "VALIDATION_ERROR"; r["error_message"] = "region_code must be a 2-letter string"
                    r["finished_at"] = _iso(now); r["updated_at"] = _iso(now)
                    break
            _save("tool_requests.json", tool_reqs)
            return _err("VALIDATION_ERROR", "region_code must be a 2-letter string")

    if channel_id is not None:
        if not isinstance(channel_id, str) or not re.match(r"^ytb_chn_[0-9A-HJKMNP-TV-Z]{10,}$", channel_id):
            tool_reqs = _load("tool_requests.json")
            for r in tool_reqs:
                if r.get("id") == req_row["id"]:
                    r["status"] = "failed"; r["http_status"] = 400
                    r["error_code"] = "VALIDATION_ERROR"; r["error_message"] = "channel_id is malformed"
                    r["finished_at"] = _iso(now); r["updated_at"] = _iso(now)
                    break
            _save("tool_requests.json", tool_reqs)
            return _err("VALIDATION_ERROR", "channel_id is malformed")

    if limit is None:
        limit = 25
    if not isinstance(limit, int) or limit < 1 or limit > 50:
        tool_reqs = _load("tool_requests.json")
        for r in tool_reqs:
            if r.get("id") == req_row["id"]:
                r["status"] = "failed"; r["http_status"] = 400
                r["error_code"] = "VALIDATION_ERROR"; r["error_message"] = "limit must be an integer between 1 and 50"
                r["finished_at"] = _iso(now); r["updated_at"] = _iso(now)
                break
        _save("tool_requests.json", tool_reqs)
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 50")

    if order is not None and order not in ("relevance", "date", "view_count", "rating"):
        tool_reqs = _load("tool_requests.json")
        for r in tool_reqs:
            if r.get("id") == req_row["id"]:
                r["status"] = "failed"; r["http_status"] = 400
                r["error_code"] = "VALIDATION_ERROR"; r["error_message"] = "order must be one of relevance,date,view_count,rating"
                r["finished_at"] = _iso(now); r["updated_at"] = _iso(now)
                break
        _save("tool_requests.json", tool_reqs)
        return _err("VALIDATION_ERROR", "order must be one of relevance,date,view_count,rating")

    if safe_search is not None and safe_search not in ("none", "moderate", "strict"):
        tool_reqs = _load("tool_requests.json")
        for r in tool_reqs:
            if r.get("id") == req_row["id"]:
                r["status"] = "failed"; r["http_status"] = 400
                r["error_code"] = "VALIDATION_ERROR"; r["error_message"] = "safe_search must be one of none,moderate,strict"
                r["finished_at"] = _iso(now); r["updated_at"] = _iso(now)
                break
        _save("tool_requests.json", tool_reqs)
        return _err("VALIDATION_ERROR", "safe_search must be one of none,moderate,strict")

    pa = _parse_dt(published_after, "published_after")
    if isinstance(pa, tuple) and pa[0] == "__bad__":
        tool_reqs = _load("tool_requests.json")
        for r in tool_reqs:
            if r.get("id") == req_row["id"]:
                r["status"] = "failed"; r["http_status"] = 400
                r["error_code"] = "VALIDATION_ERROR"; r["error_message"] = pa[1]["error"]["message"]
                r["finished_at"] = _iso(now); r["updated_at"] = _iso(now)
                break
        _save("tool_requests.json", tool_reqs)
        return pa[1]
    pb = _parse_dt(published_before, "published_before")
    if isinstance(pb, tuple) and pb[0] == "__bad__":
        tool_reqs = _load("tool_requests.json")
        for r in tool_reqs:
            if r.get("id") == req_row["id"]:
                r["status"] = "failed"; r["http_status"] = 400
                r["error_code"] = "VALIDATION_ERROR"; r["error_message"] = pb[1]["error"]["message"]
                r["finished_at"] = _iso(now); r["updated_at"] = _iso(now)
                break
        _save("tool_requests.json", tool_reqs)
        return pb[1]

    if refresh is not None and not isinstance(refresh, bool):
        tool_reqs = _load("tool_requests.json")
        for r in tool_reqs:
            if r.get("id") == req_row["id"]:
                r["status"] = "failed"; r["http_status"] = 400
                r["error_code"] = "VALIDATION_ERROR"; r["error_message"] = "refresh must be boolean"
                r["finished_at"] = _iso(now); r["updated_at"] = _iso(now)
                break
        _save("tool_requests.json", tool_reqs)
        return _err("VALIDATION_ERROR", "refresh must be boolean")

    # client status check (log failed)
    if client.get("status") != "active":
        tool_reqs = _load("tool_requests.json")
        for r in tool_reqs:
            if r.get("id") == req_row["id"]:
                r["status"] = "failed"; r["http_status"] = 403
                r["error_code"] = "CLIENT_INACTIVE"; r["error_message"] = "Client is not active"
                r["finished_at"] = _iso(now); r["updated_at"] = _iso(now)
                break
        _save("tool_requests.json", tool_reqs)
        return _err("UNAUTHORIZED", "Client is not active", error_code="CLIENT_INACTIVE")

    # transition to running
    tool_reqs = _load("tool_requests.json")
    for r in tool_reqs:
        if r.get("id") == req_row["id"]:
            r["status"] = "running"
            r["started_at"] = _iso(now)
            r["updated_at"] = _iso(now)
            break
    _save("tool_requests.json", tool_reqs)

    # estimate units
    units = 100  # heuristic for search.list
    # enforce quota and increment counters
    clients = _load("api_clients.json")
    ci = next((i for i, c in enumerate(clients) if c.get("id") == client.get("id")), None)
    if ci is None:
        # should not happen; treat as unauthorized
        tool_reqs = _load("tool_requests.json")
        for r in tool_reqs:
            if r.get("id") == req_row["id"]:
                r["status"] = "failed"; r["http_status"] = 401
                r["error_code"] = "UNAUTHORIZED"; r["error_message"] = "Client context missing"
                r["finished_at"] = _iso(now); r["updated_at"] = _iso(now)
                break
        _save("tool_requests.json", tool_reqs)
        return _err("UNAUTHORIZED", "Client context missing")
    qerr = _update_client_quota(clients[ci], units)
    if qerr:
        _save("api_clients.json", clients)
        tool_reqs = _load("tool_requests.json")
        for r in tool_reqs:
            if r.get("id") == req_row["id"]:
                r["status"] = "failed"
                r["http_status"] = 429 if qerr["error"]["code"] in ("RATE_LIMIT", "QUOTA_EXCEEDED") else 400
                r["error_code"] = qerr["error"]["code"]
                r["error_message"] = qerr["error"]["message"]
                r["youtube_units_charged"] = 0
                r["cache_hit"] = False
                r["finished_at"] = _iso(now)
                r["updated_at"] = _iso(now)
                break
        _save("tool_requests.json", tool_reqs)
        return qerr
    _save("api_clients.json", clients)

    # Resolve channel restriction
    channels = _load("channels.json")
    resolved_channel = None
    if channel_id is not None:
        resolved_channel = next((c for c in channels if c.get("id") == channel_id), None)
        if resolved_channel is None:
            # not error for search: restriction simply yields empty set
            pass
    elif youtube_channel_id is not None:
        if not isinstance(youtube_channel_id, str) or not youtube_channel_id:
            # validation
            tool_reqs = _load("tool_requests.json")
            for r in tool_reqs:
                if r.get("id") == req_row["id"]:
                    r["status"] = "failed"; r["http_status"] = 400
                    r["error_code"] = "VALIDATION_ERROR"; r["error_message"] = "youtube_channel_id must be a string"
                    r["finished_at"] = _iso(now); r["updated_at"] = _iso(now)
                    break
            _save("tool_requests.json", tool_reqs)
            return _err("VALIDATION_ERROR", "youtube_channel_id must be a string")
        resolved_channel = next((c for c in channels if c.get("youtube_channel_id") == youtube_channel_id), None)

    # Pagination token decode (opaque)
    offset = 0
    token_qhash = None
    if page_token is not None:
        if not isinstance(page_token, str) or not page_token:
            tool_reqs = _load("tool_requests.json")
            for r in tool_reqs:
                if r.get("id") == req_row["id"]:
                    r["status"] = "failed"; r["http_status"] = 400
                    r["error_code"] = "VALIDATION_ERROR"; r["error_message"] = "page_token must be a non-empty string"
                    r["finished_at"] = _iso(now); r["updated_at"] = _iso(now)
                    break
            _save("tool_requests.json", tool_reqs)
            return _err("VALIDATION_ERROR", "page_token must be a non-empty string")
        try:
            raw = base64.urlsafe_b64decode(page_token.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict) or "o" not in obj or "q" not in obj:
                raise ValueError("bad token")
            if not isinstance(obj["o"], int) or obj["o"] < 0:
                raise ValueError("bad offset")
            if not isinstance(obj["q"], str):
                raise ValueError("bad q hash")
            offset = obj["o"]
            token_qhash = obj["q"]
        except Exception:
            tool_reqs = _load("tool_requests.json")
            for r in tool_reqs:
                if r.get("id") == req_row["id"]:
                    r["status"] = "failed"; r["http_status"] = 400
                    r["error_code"] = "VALIDATION_ERROR"; r["error_message"] = "page_token is invalid"
                    r["finished_at"] = _iso(now); r["updated_at"] = _iso(now)
                    break
            _save("tool_requests.json", tool_reqs)
            return _err("VALIDATION_ERROR", "page_token is invalid")

    norm_q = _norm_query(query)
    # bind token to query+filters so tokens can't be reused across different searches
    sig_obj = {
        "q": norm_q,
        "region_code": region_code,
        "channel_id": resolved_channel.get("id") if resolved_channel else None,
        "published_after": _iso(pa) if isinstance(pa, datetime.datetime) else None,
        "published_before": _iso(pb) if isinstance(pb, datetime.datetime) else None,
        "order": order or "relevance",
        "safe_search": safe_search or "moderate",
    }
    sig = hashlib.sha256(json.dumps(sig_obj, sort_keys=True, ensure_ascii=False).encode("utf-8")).hexdigest()[:24]
    if token_qhash is not None and token_qhash != sig:
        tool_reqs = _load("tool_requests.json")
        for r in tool_reqs:
            if r.get("id") == req_row["id"]:
                r["status"] = "failed"; r["http_status"] = 400
                r["error_code"] = "VALIDATION_ERROR"; r["error_message"] = "page_token does not match this query"
                r["finished_at"] = _iso(now); r["updated_at"] = _iso(now)
                break
        _save("tool_requests.json", tool_reqs)
        return _err("VALIDATION_ERROR", "page_token does not match this query")

    # Cache behaviour: serve from local cached videos. If refresh=True, mark matching cached videos stale->active with last_fetched_at bump.
    videos = _load("videos.json")

    def _video_dt(v):
        s = v.get("published_at")
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                dt = datetime.datetime.fromisoformat(s[:-1] + "+00:00")
            else:
                dt = datetime.datetime.fromisoformat(s)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    matched = []
    for v in videos:
        if v.get("status") not in ("active", "stale"):
            continue
        if resolved_channel and v.get("channel_id") != resolved_channel.get("id"):
            continue
        # time filters
        vdt = _video_dt(v)
        if isinstance(pa, datetime.datetime) and vdt and vdt <= pa:
            continue
        if isinstance(pb, datetime.datetime) and vdt and vdt >= pb:
            continue
        # query match against title/description
        t = (v.get("title") or "")
        d = (v.get("description") or "")
        hay = (t + " " + d).lower()
        if norm_q and norm_q not in " ".join(hay.split()):
            continue
        matched.append(v)

    # sort
    ordv = order or "relevance"
    if ordv == "date":
        matched.sort(key=lambda v: (_video_dt(v) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)), reverse=True)
    elif ordv == "view_count":
        matched.sort(key=lambda v: int((v.get("stats") or {}).get("viewCount") or 0), reverse=True)
    elif ordv == "rating":
        matched.sort(key=lambda v: float((v.get("stats") or {}).get("likeCount") or 0), reverse=True)
    else:
        # simple relevance: title contains gets priority; then view_count
        def _rel(v):
            title = (v.get("title") or "").lower()
            sc = 2 if norm_q in " ".join(title.split()) else 0
            views = int((v.get("stats") or {}).get("viewCount") or 0)
            return (sc, views)
        matched.sort(key=_rel, reverse=True)

    total = len(matched)
    page = matched[offset:offset + limit]
    next_offset = offset + limit
    has_more = next_offset < total
    next_token = None
    if has_more:
        tok = {"o": next_offset, "q": sig}
        next_token = base64.urlsafe_b64encode(json.dumps(tok, separators=(",", ":"), ensure_ascii=False).encode("utf-8")).decode("utf-8").rstrip("=")

    # refresh behaviour: bump last_fetched_at and status active for returned stale videos if refresh=true
    cache_hit = True
    if refresh:
        cache_hit = False
        vid_ids = {v.get("id") for v in page if v.get("id")}
        if vid_ids:
            changed = False
            for v in videos:
                if v.get("id") in vid_ids:
                    v["last_fetched_at"] = _iso(now)
                    if v.get("status") == "stale":
                        v["status"] = "active"
                    v["updated_at"] = _iso(now)
                    changed = True
            if changed:
                _save("videos.json", videos)

    # finalize tool_request row to succeeded
    finished = datetime.datetime.now(datetime.timezone.utc)
    tool_reqs = _load("tool_requests.json")
    for r in tool_reqs:
        if r.get("id") == req_row["id"]:
            r["status"] = "succeeded"
            r["http_status"] = 200
            r["youtube_units_charged"] = units
            r["cache_hit"] = cache_hit
            r["normalized_query"] = norm_q
            r["region_code"] = region_code
            r["resolved_channel_id"] = resolved_channel.get("id") if resolved_channel else None
            # store minimal response payload for debugging
            r["response_payload"] = {
                "count": len(page),
                "total": total,
                "next_page_token": next_token,
            }
            r["finished_at"] = _iso(finished)
            r["updated_at"] = _iso(finished)
            break
    _save("tool_requests.json", tool_reqs)

    return {
        "videos": page,
        "next_page_token": next_token,
        "meta": {
            "total": total,
            "limit": limit,
            "offset": offset,
            "has_more": has_more,
            "normalized_query": norm_q,
            "cache_hit": cache_hit,
            "youtube_units_charged": units,
            "latency_ms": int((time.time() - t0) * 1000),
        }
    }

def get_video_details(youtube_video_id=None, video_id=None, refresh=None, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0248000" if __import__("os").path.isdir("./environment_mix/0248000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str): return dt
        if dt.tzinfo is None: dt = dt.replace(tzinfo=datetime.timezone.utc)
