        for c in clients:
            if c.get("status") == "active":
                return c, clients
        return None, clients

    def _log_tool_request(tool_requests, client_id, req_id, status, input_params,
                          youtube_video_id=None, resolved_video_id=None, resolved_channel_id=None,
                          http_status=None, error_code=None, error_message=None,
                          youtube_units_charged=0, cache_hit=False, response_payload=None,
                          started_at=None, finished_at=None, normalized_query=None, region_code=None, youtube_channel_id=None):
        row = {
            "id": req_id,
            "client_id": client_id,
            "tool_name": "get_video_details",
            "input_params": input_params,
            "normalized_query": normalized_query,
            "region_code": region_code,
            "youtube_video_id": youtube_video_id,
            "youtube_channel_id": youtube_channel_id,
            "resolved_video_id": resolved_video_id,
            "resolved_channel_id": resolved_channel_id,
            "response_payload": _truncate_payload(response_payload) if response_payload is not None else None,
            "http_status": http_status,
            "error_code": error_code,
            "error_message": error_message,
            "youtube_units_charged": int(youtube_units_charged or 0),
            "cache_hit": bool(cache_hit),
            "status": status,
            "started_at": started_at,
            "finished_at": finished_at,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        tool_requests.append(row)
        return row

    def _transition_req(row, new_status, **updates):
        transitions = {
            "received": ["running", "cancelled"],
            "running": ["succeeded", "failed", "cancelled"],
            "succeeded": [],
            "failed": [],
            "cancelled": [],
        }
        cur = row.get("status")
        if new_status not in transitions.get(cur, []):
            return False
        row["status"] = new_status
        for k, v in updates.items():
            row[k] = v
        row["updated_at"] = _iso(now)
        return True

    def _enforce_and_charge(client_row, clients_all, tool_requests_all, units):
        qra = _parse_dt(client_row.get("quota_reset_at")) or now
        if qra <= now:
            client_row["requests_used_today"] = 0
            client_row["youtube_units_used_today"] = 0
            client_row["quota_reset_at"] = _iso(_next_reset_boundary(now))
        ru = client_row.get("requests_used_today")
        yu = client_row.get("youtube_units_used_today")
        qdr = client_row.get("quota_daily_requests")
        qdu = client_row.get("quota_daily_youtube_units")
        if not isinstance(qdr, int) or qdr < 0 or not isinstance(qdu, int) or qdu < 0:
            return _err("VALIDATION_ERROR", "Client quota configuration invalid")
        if not isinstance(ru, int) or ru < 0: ru = 0
        if not isinstance(yu, int) or yu < 0: yu = 0
        units = int(units or 0)
        if units < 0:
            return _err("VALIDATION_ERROR", "youtube_units_charged must be >= 0")
        if ru + 1 > qdr:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded", quota="quota_daily_requests")
        if yu + units > qdu:
            return _err("QUOTA_EXCEEDED", "Daily YouTube units quota exceeded", quota="quota_daily_youtube_units")
        client_row["requests_used_today"] = ru + 1
        client_row["youtube_units_used_today"] = yu + units
        client_row["updated_at"] = _iso(now)
        _save("api_clients.json", clients_all)
        return None

    # Validation: accept oneOf semantics, but do NOT reject when both are provided (audit showed real calls provide both).
    if youtube_video_id is None and video_id is None:
        # Must still log a failed request
        client_row, clients_all = _pick_active_client()
        tool_requests = _load("tool_requests.json")
        req_id = _gen_id("ytb_req_")
        req = _log_tool_request(tool_requests, client_row["id"] if client_row else None, req_id, "received",
                                {"youtube_video_id": youtube_video_id, "video_id": video_id, "refresh": refresh},
                                youtube_video_id=youtube_video_id)
        _transition_req(req, "running", started_at=_iso(now))
        _transition_req(req, "failed", finished_at=_iso(now), http_status=400, error_code="INVALID_ARGUMENT",
                        error_message="Either youtube_video_id or video_id is required")
        _save("tool_requests.json", tool_requests)
        return _err("VALIDATION_ERROR", "Either youtube_video_id or video_id is required")

    if youtube_video_id is not None and (not isinstance(youtube_video_id, str) or not youtube_video_id.strip()):
        return _err("VALIDATION_ERROR", "youtube_video_id must be a non-empty string")
    if video_id is not None:
        if not isinstance(video_id, str) or not re.match(r"^ytb_vid_[0-9A-HJKMNP-TV-Z]{10,}$", video_id):
            return _err("VALIDATION_ERROR", "video_id must match ^ytb_vid_[0-9A-HJKMNP-TV-Z]{10,}$")
    if refresh is not None and not isinstance(refresh, bool):
        return _err("VALIDATION_ERROR", "refresh must be a boolean")

    # Resolve ambient client (no api_key parameter on this tool)
    client_row, clients_all = _pick_active_client()
    tool_requests = _load("tool_requests.json")
    req_id = _gen_id("ytb_req_")

    if client_row is None:
        # log failed as unauthorized
        req = _log_tool_request(tool_requests, None, req_id, "received",
                                {"youtube_video_id": youtube_video_id, "video_id": video_id, "refresh": refresh},
                                youtube_video_id=youtube_video_id)
        _transition_req(req, "running", started_at=_iso(now))
        _transition_req(req, "failed", finished_at=_iso(now), http_status=401, error_code="UNAUTHORIZED",
                        error_message="No active client context available")
        _save("tool_requests.json", tool_requests)
        return _err("UNAUTHORIZED", "Unauthorized")

    # Client must be active; if inactive, reject and log
    if client_row.get("status") != "active":
        req = _log_tool_request(tool_requests, client_row["id"], req_id, "received",
                                {"youtube_video_id": youtube_video_id, "video_id": video_id, "refresh": refresh},
                                youtube_video_id=youtube_video_id)
        _transition_req(req, "running", started_at=_iso(now))
        _transition_req(req, "failed", finished_at=_iso(now), http_status=403, error_code="CLIENT_INACTIVE",
                        error_message="Client is not active")
        _save("tool_requests.json", tool_requests)
        return _err("UNAUTHORIZED", "Client inactive", error_code="CLIENT_INACTIVE")

    # Estimate units: details fetch 1 unit; if refresh true charge 2 (simulate upstream)
    units = 2 if refresh else 1
    req = _log_tool_request(tool_requests, client_row["id"], req_id, "received",
                            {"youtube_video_id": youtube_video_id, "video_id": video_id, "refresh": refresh},
                            youtube_video_id=youtube_video_id,
                            youtube_units_charged=units, cache_hit=not bool(refresh))
    _transition_req(req, "running", started_at=_iso(now))

    quota_err = _enforce_and_charge(client_row, clients_all, tool_requests, units)
    if quota_err:
        _transition_req(req, "failed", finished_at=_iso(now), http_status=429,
                        error_code=quota_err["error"]["code"], error_message=quota_err["error"]["message"])
        _save("tool_requests.json", tool_requests)
        return quota_err

    videos = _load("videos.json")
    channels = _load("channels.json")

    # Resolve by video_id preferentially if it exists; else by youtube_video_id
    vrow = None
    if video_id is not None:
        for v in videos:
            if v.get("id") == video_id:
                vrow = v
                break
        if vrow is None:
            _transition_req(req, "failed", finished_at=_iso(now), http_status=404,
                            error_code="NOT_FOUND", error_message="Unknown video_id")
            _save("tool_requests.json", tool_requests)
            return _err("NOT_FOUND", "Unknown video_id")
    if vrow is None and youtube_video_id is not None:
        for v in videos:
            if v.get("youtube_video_id") == youtube_video_id:
                vrow = v
                break
        if vrow is None:
            _transition_req(req, "failed", finished_at=_iso(now), http_status=404,
                            error_code="NOT_FOUND", error_message="Unable to resolve youtube_video_id")
            _save("tool_requests.json", tool_requests)
            return _err("NOT_FOUND", "Unable to resolve youtube_video_id")

    # Policy: do not serve tombstoned/unavailable as active metadata
    if vrow.get("status") in ("tombstoned", "unavailable"):
        _transition_req(req, "failed", finished_at=_iso(now), http_status=404,
                        error_code="UPSTREAM_NOT_FOUND", error_message="Video unavailable")
        _save("tool_requests.json", tool_requests)
        return _err("NOT_FOUND", "Video unavailable")

    # Refresh semantics: update last_fetched_at + status active (unless unavailable) and updated_at
    if refresh:
        vrow["last_fetched_at"] = _iso(now)
        if vrow.get("status") in ("stale",):
            vrow["status"] = "active"
        vrow["updated_at"] = _iso(now)
        _save("videos.json", videos)

    # Resolve channel id if possible
    resolved_channel_id = vrow.get("channel_id")
    if resolved_channel_id:
        ch = next((c for c in channels if c.get("id") == resolved_channel_id), None)
        if ch and refresh:
            ch["last_fetched_at"] = _iso(now)
            if ch.get("status") == "stale":
                ch["status"] = "active"
            ch["updated_at"] = _iso(now)
            _save("channels.json", channels)

    req["resolved_video_id"] = vrow.get("id")
    req["resolved_channel_id"] = resolved_channel_id
    req["cache_hit"] = not bool(refresh)
    req["response_payload"] = _truncate_payload(vrow)
    _transition_req(req, "succeeded", finished_at=_iso(now), http_status=200)
    _save("tool_requests.json", tool_requests)

    return {"video": vrow}

