                   {"youtube_video_id": youtube_video_id, "video_id": video_id, "order": order, "limit": limit, "page_token": page_token,
                    "include_replies": include_replies, "refresh": refresh},
                   youtube_video_id=youtube_video_id)
        _transition(req, "running", started_at=_iso(now))
        _transition(req, "failed", finished_at=_iso(now), http_status=400, error_code="INVALID_ARGUMENT",
                    error_message="Either youtube_video_id or video_id is required for get_video_comments")
