        _save("tool_requests.json", tool_requests)
        return _err("UNAUTHORIZED", "Client inactive", error_code="CLIENT_INACTIVE")

    # Units: base 1; include_replies adds 1; refresh adds 1
    units = 1 + (1 if include_replies else 0) + (1 if refresh else 0)

    req = _log(tool_requests, client_row["id"], req_id, "received",
               {"youtube_video_id": youtube_video_id, "video_id": video_id, "order": order, "limit": limit, "page_token": page_token,
