    if refresh:
        changed = False
        for a in v_assets:
            a["status"] = "stale" if a.get("status") == "available" else a.get("status")
            a["last_fetched_at"] = _iso(now)
            a["updated_at"] = _iso(now)
            changed = True
        if changed:
            _save("video_text_assets.json", assets)

