    comments = []
    for a in v_assets:
        if a.get("status") in ("tombstoned",):
            continue
        comments.append({
            "id": a.get("id"),
            "youtube_comment_id": a.get("youtube_asset_id"),
            "text": a.get("text"),
            "author_display_name": a.get("author_display_name"),
            "author_channel_youtube_id": a.get("author_channel_youtube_id"),
            "like_count": a.get("like_count"),
            "published_at": a.get("published_at"),
            "status": a.get("status"),
            "source": a.get("source"),
        })

    # Sort
    if order == "relevance":
        comments.sort(key=lambda x: (x.get("like_count") or 0, x.get("published_at") or ""), reverse=True)
    else:
        comments.sort(key=lambda x: (x.get("published_at") or ""), reverse=True)

    # Pagination by opaque token encoding offset
    offset = 0
    if page_token:
        try:
            raw = base64.urlsafe_b64decode(page_token.encode("utf-8") + b"===")
            tok = raw.decode("utf-8")
            if tok.startswith("off:"):
                offset = int(tok.split(":", 1)[1])
        except Exception:
            # invalid token => validation error (and log fail)
            _transition(req, "failed", finished_at=_iso(now), http_status=400, error_code="INVALID_ARGUMENT",
                        error_message="Invalid page_token")
            _save("tool_requests.json", tool_requests)
            return _err("VALIDATION_ERROR", "Invalid page_token")

    page = comments[offset:offset + limit]
    next_offset = offset + limit
    next_page_token = None
    if next_offset < len(comments):
        next_page_token = base64.urlsafe_b64encode(("off:%d" % next_offset).encode("utf-8")).decode("utf-8").rstrip("=")

    payload = {"comments": page, "next_page_token": next_page_token}
    req["cache_hit"] = not bool(refresh)
    req["response_payload"] = _truncate_payload(payload)
    _transition(req, "succeeded", finished_at=_iso(now), http_status=200)
    _save("tool_requests.json", tool_requests)
    return payload

