        vrow = next((v for v in videos if v.get("youtube_video_id") == youtube_video_id), None)
        if vrow is None:
            _transition(req, "failed", finished_at=_iso(now), http_status=404, error_code="NOT_FOUND",
                        error_message="Unable to resolve youtube_video_id")
            _save("tool_requests.json", tool_requests)
            return _err("NOT_FOUND", "Unable to resolve youtube_video_id")

    if vrow.get("status") in ("tombstoned", "unavailable"):
        _transition(req, "failed", finished_at=_iso(now), http_status=404, error_code="UPSTREAM_NOT_FOUND",
                    error_message="Video unavailable")
        _save("tool_requests.json", tool_requests)
        return _err("NOT_FOUND", "Video unavailable")

    req["resolved_video_id"] = vrow.get("id")
    req["resolved_channel_id"] = vrow.get("channel_id")

    # Transcript selection
    candidates = [a for a in assets if a.get("video_id") == vrow.get("id") and a.get("asset_type") == "transcript"]
    # Allowed statuses: available, stale; unavailable triggers attempt re-extraction (simulated)
    usable = [a for a in candidates if a.get("status") in ("available", "stale")]

    # Filter by language / auto-generated policy
    def _lang_score(a):
        al = (a.get("language") or "").strip()
        if language is None or not language:
            return 0
        if al.lower() == language.lower():
            return 2
        if al and language and al.split("-")[0].lower() == language.split("-")[0].lower():
            return 1
        return 0

    def _auto_ok(a):
        if include_auto_generated:
            return True
        # default: prefer human captions; if is_auto_generated is None treat as acceptable
        return (a.get("is_auto_generated") is not True)

    usable = [a for a in usable if _auto_ok(a)]
    usable.sort(key=lambda a: (_lang_score(a), 1 if a.get("status") == "available" else 0), reverse=True)

    transcript_asset = usable[0] if usable else None

    if refresh or transcript_asset is None:
        # Attempt re-extraction: if we have an unavailable asset, flip to stale and bump timestamps; else if none, cannot extract offline -> fail
        unavailable = [a for a in candidates if a.get("status") == "unavailable"]
        if unavailable:
            # Simulate re-extraction attempt: mark stale (not guaranteed available)
            a = unavailable[0]
            a["status"] = "stale"
            a["last_fetched_at"] = _iso(now)
            a["updated_at"] = _iso(now)
            _save("video_text_assets.json", assets)
            transcript_asset = a
        elif transcript_asset is None:
            _transition(req, "failed", finished_at=_iso(now), http_status=404, error_code="UPSTREAM_NOT_FOUND",
                        error_message="Transcript not available for this video.")
            _save("tool_requests.json", tool_requests)
            return _err("NOT_FOUND", "Transcript not available for this video.")

    # If still unavailable (policy)
    if transcript_asset.get("status") == "unavailable":
        _transition(req, "failed", finished_at=_iso(now), http_status=404, error_code="UPSTREAM_NOT_FOUND",
                    error_message="Transcript unavailable")
        _save("tool_requests.json", tool_requests)
        return _err("NOT_FOUND", "Transcript unavailable")

    segments = transcript_asset.get("segments") if isinstance(transcript_asset.get("segments"), list) else None
    if format == "segments":
        out = {"video_id": vrow.get("id"), "youtube_video_id": vrow.get("youtube_video_id"), "language": transcript_asset.get("language"),
               "is_auto_generated": transcript_asset.get("is_auto_generated"), "segments": segments or []}
    else:
        text = transcript_asset.get("text")
        if (text is None or text == "") and segments:
            text = " ".join([str(s.get("text") or "").strip() for s in segments]).strip()
        out = {"video_id": vrow.get("id"), "youtube_video_id": vrow.get("youtube_video_id"), "language": transcript_asset.get("language"),
               "is_auto_generated": transcript_asset.get("is_auto_generated"), "text": text or ""}

    req["cache_hit"] = not bool(refresh)
    req["response_payload"] = _truncate_payload(out)
    _transition(req, "succeeded", finished_at=_iso(now), http_status=200)
    _save("tool_requests.json", tool_requests)
    return out

def get_related_videos(youtube_video_id=None, video_id=None, region_code=None, language=None, limit=None, page_token=None, refresh=None, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0248000" if __import__("os").path.isdir("./environment_mix/0248000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str): return dt
        if dt.tzinfo is None: dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(x):
        if x is None: return None
        if isinstance(x, datetime.datetime):
            return x if x.tzinfo else x.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(x, str): return None
        s = x.strip()
        if s.endswith("Z"): s = s[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(s)
        except ValueError:
            return None
        return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)

    _B32 = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _gen_id(prefix):
        ms = int(time.time() * 1000)
        tpart = ms
        out = []
        for _ in range(10):
            out.append(_B32[tpart % 32]); tpart //= 32
        rnd = int.from_bytes(os.urandom(10), "big")
        for _ in range(16):
            out.append(_B32[rnd % 32]); rnd //= 32
        return prefix + "".join(reversed(out))

    def _next_reset_boundary(dt):
        dt = dt.astimezone(datetime.timezone.utc)
        d = dt.date() + datetime.timedelta(days=1)
        return datetime.datetime(d.year, d.month, d.day, tzinfo=datetime.timezone.utc)

    def _truncate_payload(obj, limit=50000):
        try:
            s = json.dumps(obj, ensure_ascii=False)
        except Exception:
            return {"note": "non-serializable payload"}
        if len(s) <= limit:
            return obj
        return {"truncated": True, "chars": len(s), "preview": s[:limit]}

    def _pick_active_client():
        clients = _load("api_clients.json")
        for c in clients:
            if c.get("status") == "active":
                return c, clients
        return None, clients

    def _log(tool_requests, client_id, req_id, status, input_params,
             youtube_video_id=None, region_code=None,
             resolved_video_id=None, resolved_channel_id=None,
             http_status=None, error_code=None, error_message=None,
             youtube_units_charged=0, cache_hit=False, response_payload=None):
        row = {
            "id": req_id,
            "client_id": client_id,
            "tool_name": "get_related_videos",
            "input_params": input_params,
            "normalized_query": None,
            "region_code": region_code,
            "youtube_video_id": youtube_video_id,
            "youtube_channel_id": None,
            "resolved_video_id": resolved_video_id,
            "resolved_channel_id": resolved_channel_id,
            "response_payload": _truncate_payload(response_payload) if response_payload is not None else None,
            "http_status": http_status,
            "error_code": error_code,
            "error_message": error_message,
            "youtube_units_charged": int(youtube_units_charged or 0),
            "cache_hit": bool(cache_hit),
            "status": status,
            "started_at": None,
            "finished_at": None,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        tool_requests.append(row)
        return row

    def _transition(row, new_status, **updates):
        transitions = {
            "received": ["running", "cancelled"],
            "running": ["succeeded", "failed", "cancelled"],
            "succeeded": [],
            "failed": [],
            "cancelled": [],
        }
        cur = row.get("status")
        if new_status not in transitions.get(cur, []):
            return False
        row["status"] = new_status
        for k, v in updates.items():
            row[k] = v
        row["updated_at"] = _iso(now)
        return True

    def _enforce_and_charge(client_row, clients_all, units):
        qra = _parse_dt(client_row.get("quota_reset_at")) or now
        if qra <= now:
            client_row["requests_used_today"] = 0
            client_row["youtube_units_used_today"] = 0
            client_row["quota_reset_at"] = _iso(_next_reset_boundary(now))
        ru = client_row.get("requests_used_today")
        yu = client_row.get("youtube_units_used_today")
        qdr = client_row.get("quota_daily_requests")
        qdu = client_row.get("quota_daily_youtube_units")
        if not isinstance(qdr, int) or qdr < 0 or not isinstance(qdu, int) or qdu < 0:
            return _err("VALIDATION_ERROR", "Client quota configuration invalid")
        if not isinstance(ru, int) or ru < 0: ru = 0
        if not isinstance(yu, int) or yu < 0: yu = 0
        units = int(units or 0)
        if ru + 1 > qdr:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded", quota="quota_daily_requests")
        if yu + units > qdu:
            return _err("QUOTA_EXCEEDED", "Daily YouTube units quota exceeded", quota="quota_daily_youtube_units")
        client_row["requests_used_today"] = ru + 1
        client_row["youtube_units_used_today"] = yu + units
        client_row["updated_at"] = _iso(now)
        _save("api_clients.json", clients_all)
        return None

    # Validation (relaxed oneOf)
    if youtube_video_id is None and video_id is None:
        client_row, clients_all = _pick_active_client()
        tool_requests = _load("tool_requests.json")
        req_id = _gen_id("ytb_req_")
        req = _log(tool_requests, client_row["id"] if client_row else None, req_id, "received",
                   {"youtube_video_id": youtube_video_id, "video_id": video_id, "region_code": region_code, "language": language,
                    "limit": limit, "page_token": page_token, "refresh": refresh},
                   youtube_video_id=youtube_video_id, region_code=region_code)
        _transition(req, "running", started_at=_iso(now))
        _transition(req, "failed", finished_at=_iso(now), http_status=400, error_code="INVALID_ARGUMENT",
                    error_message="Either youtube_video_id or video_id is required for get_related_videos")
        _save("tool_requests.json", tool_requests)
        return _err("VALIDATION_ERROR", "Either youtube_video_id or video_id is required")

    if youtube_video_id is not None and (not isinstance(youtube_video_id, str) or not youtube_video_id.strip()):
        return _err("VALIDATION_ERROR", "youtube_video_id must be a non-empty string")
    if video_id is not None:
        if not isinstance(video_id, str) or not re.match(r"^ytb_vid_[0-9A-HJKMNP-TV-Z]{10,}$", video_id):
            return _err("VALIDATION_ERROR", "video_id must match ^ytb_vid_[0-9A-HJKMNP-TV-Z]{10,}$")
    if region_code is not None:
        if not isinstance(region_code, str) or len(region_code.strip()) != 2:
            return _err("VALIDATION_ERROR", "region_code must be a 2-letter string")
        region_code = region_code.strip().upper()
    if language is not None and (not isinstance(language, str) or not language.strip()):
        return _err("VALIDATION_ERROR", "language must be a non-empty string")
    if limit is None:
        limit = 25
    if not isinstance(limit, int) or limit < 1 or limit > 50:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 50")
    if page_token is not None and (not isinstance(page_token, str) or not page_token.strip()):
        return _err("VALIDATION_ERROR", "page_token must be a non-empty string")
    if refresh is not None and not isinstance(refresh, bool):
        return _err("VALIDATION_ERROR", "refresh must be a boolean")

    client_row, clients_all = _pick_active_client()
    tool_requests = _load("tool_requests.json")
    req_id = _gen_id("ytb_req_")

    if client_row is None:
        req = _log(tool_requests, None, req_id, "received",
                   {"youtube_video_id": youtube_video_id, "video_id": video_id, "region_code": region_code, "language": language,
                    "limit": limit, "page_token": page_token, "refresh": refresh},
                   youtube_video_id=youtube_video_id, region_code=region_code)
        _transition(req, "running", started_at=_iso(now))
        _transition(req, "failed", finished_at=_iso(now), http_status=401, error_code="UNAUTHORIZED",
                    error_message="No active client context available")
        _save("tool_requests.json", tool_requests)
        return _err("UNAUTHORIZED", "Unauthorized")

    if client_row.get("status") != "active":
        req = _log(tool_requests, client_row["id"], req_id, "received",
                   {"youtube_video_id": youtube_video_id, "video_id": video_id, "region_code": region_code, "language": language,
                    "limit": limit, "page_token": page_token, "refresh": refresh},
                   youtube_video_id=youtube_video_id, region_code=region_code)
        _transition(req, "running", started_at=_iso(now))
        _transition(req, "failed", finished_at=_iso(now), http_status=403, error_code="CLIENT_INACTIVE",
                    error_message="Client is not active")
        _save("tool_requests.json", tool_requests)
        return _err("UNAUTHORIZED", "Client inactive", error_code="CLIENT_INACTIVE")

    units = 2 if refresh else 1
    req = _log(tool_requests, client_row["id"], req_id, "received",
               {"youtube_video_id": youtube_video_id, "video_id": video_id, "region_code": region_code, "language": language,
                "limit": limit, "page_token": page_token, "refresh": refresh},
               youtube_video_id=youtube_video_id, region_code=region_code,
               youtube_units_charged=units, cache_hit=not bool(refresh))
    _transition(req, "running", started_at=_iso(now))

    qerr = _enforce_and_charge(client_row, clients_all, units)
    if qerr:
        _transition(req, "failed", finished_at=_iso(now), http_status=429,
                    error_code=qerr["error"]["code"], error_message=qerr["error"]["message"])
        _save("tool_requests.json", tool_requests)
        return qerr

    videos = _load("videos.json")
    # Resolve seed video
    seed = None
    if video_id is not None:
        seed = next((v for v in videos if v.get("id") == video_id), None)
        if seed is None:
            _transition(req, "failed", finished_at=_iso(now), http_status=404, error_code="NOT_FOUND",
                        error_message="Unknown video_id")
            _save("tool_requests.json", tool_requests)
            return _err("NOT_FOUND", "Unknown video_id")
    if seed is None and youtube_video_id is not None:
        seed = next((v for v in videos if v.get("youtube_video_id") == youtube_video_id), None)
        if seed is None:
            _transition(req, "failed", finished_at=_iso(now), http_status=404, error_code="NOT_FOUND",
                        error_message="Unable to resolve youtube_video_id")
            _save("tool_requests.json", tool_requests)
            return _err("NOT_FOUND", "Unable to resolve youtube_video_id")

    if seed.get("status") in ("tombstoned", "unavailable"):
        _transition(req, "failed", finished_at=_iso(now), http_status=404, error_code="UPSTREAM_NOT_FOUND",
                    error_message="Video unavailable")
        _save("tool_requests.json", tool_requests)
        return _err("NOT_FOUND", "Video unavailable")

    req["resolved_video_id"] = seed.get("id")
    req["resolved_channel_id"] = seed.get("channel_id")

    # Build "related": same channel first, then others; exclude seed; only active/stale
    pool = [v for v in videos if v.get("id") != seed.get("id") and v.get("status") in ("active", "stale")]
    same_channel = [v for v in pool if v.get("channel_id") == seed.get("channel_id")]
    other = [v for v in pool if v.get("channel_id") != seed.get("channel_id")]
    related = same_channel + other

    # Pagination offset token
    offset = 0
    if page_token:
        try:
            raw = base64.urlsafe_b64decode(page_token.encode("utf-8") + b"===")
            tok = raw.decode("utf-8")
            if tok.startswith("off:"):
                offset = int(tok.split(":", 1)[1])
        except Exception:
            _transition(req, "failed", finished_at=_iso(now), http_status=400, error_code="INVALID_ARGUMENT",
                        error_message="Invalid page_token")
            _save("tool_requests.json", tool_requests)
            return _err("VALIDATION_ERROR", "Invalid page_token")

    page = related[offset:offset + limit]
    next_offset = offset + limit
    next_page_token = None
    if next_offset < len(related):
        next_page_token = base64.urlsafe_b64encode(("off:%d" % next_offset).encode("utf-8")).decode("utf-8").rstrip("=")

    out = {"videos": page, "next_page_token": next_page_token}
    req["cache_hit"] = not bool(refresh)
    req["response_payload"] = _truncate_payload(out)
    _transition(req, "succeeded", finished_at=_iso(now), http_status=200)
    _save("tool_requests.json", tool_requests)
    return out

def get_trending_videos(region_code, category_id=None, limit=None, page_token=None, refresh=None, **_extra):
    import json, os, datetime, time, re, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0248000" if __import__("os").path.isdir("./environment_mix/0248000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    start_t = time.time()
    now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    now_iso = now.isoformat()

    def _parse_dt(s):
        if s is None: return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str): return None
        try:
            if s.endswith("Z"): s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _next_reset_boundary(dt):
        dt = dt.astimezone(datetime.timezone.utc)
        return (dt + datetime.timedelta(days=1)).replace(hour=0, minute=0, second=0, microsecond=0)

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(time.time() * 1000)
        tpart = ms
        out = []
        for _ in range(10):
            out.append(alphabet[tpart % 32]); tpart //= 32
        rnd = int.from_bytes(os.urandom(10), "big")
        for _ in range(16):
            out.append(alphabet[rnd % 32]); rnd //= 32
        return prefix + "".join(reversed(out))

    def _log_request(tool_name, client_id, input_params, region_code=None,
                     status="received", http_status=None, error_code=None, error_message=None,
                     youtube_units_charged=0, cache_hit=False, response_payload=None, started_at=None, finished_at=None,
                     req_id=None):
        tool_requests = _load("tool_requests.json")
        if req_id is None:
            req_id = _gen_id("ytb_req_")
        row = {
            "id": req_id,
            "client_id": client_id,
            "tool_name": tool_name,
            "input_params": input_params if isinstance(input_params, dict) else {},
            "normalized_query": None,
            "region_code": region_code,
            "youtube_video_id": None,
            "youtube_channel_id": None,
            "resolved_video_id": None,
            "resolved_channel_id": None,
            "response_payload": response_payload,
            "http_status": http_status,
            "error_code": error_code,
            "error_message": error_message,
            "youtube_units_charged": int(youtube_units_charged or 0),
            "cache_hit": bool(cache_hit),
            "status": status,
            "started_at": started_at,
            "finished_at": finished_at,
            "created_at": now_iso,
            "updated_at": now_iso
        }
        tool_requests.append(row)
        _save("tool_requests.json", tool_requests)
        return req_id

    def _update_request(req_id, **patch):
        tool_requests = _load("tool_requests.json")
        transitions = {
            "received": ["running", "cancelled"],
            "running": ["succeeded", "failed", "cancelled"],
            "succeeded": [],
            "failed": [],
            "cancelled": []
        }
        for r in tool_requests:
            if r.get("id") == req_id:
                cur = r.get("status")
                nxt = patch.get("status", cur)
                if nxt != cur and nxt not in transitions.get(cur, []):
                    r["status"] = "failed" if cur in ("received", "running") else cur
                    r["error_code"] = r.get("error_code") or "INVALID_TRANSITION"
                    r["error_message"] = r.get("error_message") or f"Illegal transition {cur}->{nxt}"
                    r["http_status"] = r.get("http_status") or 500
                    r["updated_at"] = now_iso
                    _save("tool_requests.json", tool_requests)
                    return False
                for k, v in patch.items():
                    r[k] = v
                r["updated_at"] = now_iso
                _save("tool_requests.json", tool_requests)
                return True
        return False

    def _select_authorized_client():
        for c in _load("api_clients.json"):
            if c.get("status") == "active":
                return c
        return None

    def _maybe_reset_quota(client):
        reset_at = _parse_dt(client.get("quota_reset_at"))
        if reset_at is None or reset_at <= now:
            client["requests_used_today"] = 0
            client["youtube_units_used_today"] = 0
            client["quota_reset_at"] = _next_reset_boundary(now).isoformat()
            client["updated_at"] = now_iso

    def _charge_quota(client, units):
        req_used = int(client.get("requests_used_today") or 0)
        yt_used = int(client.get("youtube_units_used_today") or 0)
        q_req = int(client.get("quota_daily_requests") or 0)
        q_yt = int(client.get("quota_daily_youtube_units") or 0)
        if req_used + 1 > q_req:
            return "QUOTA_EXCEEDED", "Daily request quota exceeded"
        if yt_used + int(units) > q_yt:
            return "QUOTA_EXCEEDED", "Daily YouTube units quota exceeded"
        client["requests_used_today"] = req_used + 1
        client["youtube_units_used_today"] = yt_used + int(units)
        client["updated_at"] = now_iso
        return None, None

    def _persist_client(client):
        clients = _load("api_clients.json")
        for i, c in enumerate(clients):
            if c.get("id") == client.get("id"):
                clients[i] = client
                _save("api_clients.json", clients)
                return True
        return False

    def _validate():
        if not isinstance(region_code, str):
            return _err("VALIDATION_ERROR", "region_code must be a string")
        if len(region_code) != 2:
            return _err("VALIDATION_ERROR", "region_code must be length 2")
        if category_id is not None and not isinstance(category_id, str):
            return _err("VALIDATION_ERROR", "category_id must be a string")
        if limit is None:
            lim = 20
        else:
            if not isinstance(limit, int):
                return _err("VALIDATION_ERROR", "limit must be an integer")
            if limit < 1 or limit > 50:
                return _err("VALIDATION_ERROR", "limit must be between 1 and 50")
            lim = limit
        if page_token is not None and not isinstance(page_token, str):
            return _err("VALIDATION_ERROR", "page_token must be a string")
        if refresh is not None and not isinstance(refresh, bool):
            return _err("VALIDATION_ERROR", "refresh must be boolean")
        return lim

    client = _select_authorized_client()
    if client is None:
        return _err("UNAUTHORIZED", "No authorized client context available")

    _maybe_reset_quota(client)

    input_params = {
        "region_code": region_code,
        "category_id": category_id,
        "limit": limit,
        "page_token": page_token,
        "refresh": refresh
    }

    req_id = _log_request(
        tool_name="get_trending_videos",
        client_id=client["id"],
        input_params=input_params,
        region_code=region_code,
        status="received"
    )

    lim_or_err = _validate()
    if isinstance(lim_or_err, dict) and "error" in lim_or_err:
        _update_request(req_id, status="running", started_at=now_iso, http_status=400)
        _update_request(req_id, status="failed", finished_at=now_iso, http_status=400,
                        error_code="VALIDATION_ERROR", error_message=lim_or_err["error"]["message"])
        _persist_client(client)
        return lim_or_err
    lim = lim_or_err

    if client.get("status") != "active":
        _update_request(req_id, status="running", started_at=now_iso, http_status=403)
        _update_request(req_id, status="failed", finished_at=now_iso, http_status=403,
                        error_code="CLIENT_INACTIVE", error_message="Client is not active")
        _persist_client(client)
        return _err("UNAUTHORIZED", "Client inactive", error_code="CLIENT_INACTIVE")

    units = 4
    qcode, qmsg = _charge_quota(client, units)
    if qcode:
        _update_request(req_id, status="running", started_at=now_iso, http_status=429)
        _update_request(req_id, status="failed", finished_at=now_iso, http_status=429,
                        error_code=qcode, error_message=qmsg)
        _persist_client(client)
        return _err(qcode, qmsg)

    _update_request(req_id, status="running", started_at=now_iso, youtube_units_charged=units)

    videos = _load("videos.json")

    # Offline "trending": highest viewCount (stats.view_count) in last 7 days; fallback to newest.
    cutoff = now - datetime.timedelta(days=7)

    def _view_count(v):
        s = v.get("stats") or {}
        vc = s.get("viewCount") if isinstance(s, dict) else None
        if vc is None:
            vc = s.get("view_count") if isinstance(s, dict) else None
        try:
            return int(vc)
        except Exception:
            return 0

    cands = []
    for v in videos:
        if v.get("status") in ("tombstoned", "unavailable"):
            continue
        if category_id is not None and v.get("category_id") != category_id:
            continue
        pub = _parse_dt(v.get("published_at")) or _parse_dt(v.get("created_at"))
        if pub and pub >= cutoff:
            cands.append(v)

    if not cands:
        # fallback to any active/stale cached videos
        for v in videos:
            if v.get("status") in ("tombstoned", "unavailable"):
                continue
            if category_id is not None and v.get("category_id") != category_id:
                continue
            cands.append(v)

    def _sort_key(v):
        pub = _parse_dt(v.get("published_at")) or _parse_dt(v.get("created_at")) or now
        return (_view_count(v), pub)

    cands.sort(key=_sort_key, reverse=True)

    offset = 0
    if page_token:
        try:
            raw = base64.urlsafe_b64decode(page_token.encode("utf-8") + b"===")
            offset = int(raw.decode("utf-8"))
            if offset < 0:
                raise ValueError()
        except Exception:
            _update_request(req_id, status="failed", finished_at=now_iso, http_status=400,
                            error_code="VALIDATION_ERROR", error_message="Invalid page_token",
                            youtube_units_charged=units, cache_hit=True)
            _persist_client(client)
            return _err("VALIDATION_ERROR", "Invalid page_token")

    page = cands[offset:offset + lim]
    next_offset = offset + lim
    next_token = None
    if next_offset < len(cands):
        next_token = base64.urlsafe_b64encode(str(next_offset).encode("utf-8")).decode("utf-8").rstrip("=")

    items = []
    for v in page:
        items.append({
            "video_id": v.get("id"),
            "youtube_video_id": v.get("youtube_video_id"),
            "channel_id": v.get("channel_id"),
            "title": v.get("title"),
            "published_at": v.get("published_at"),
            "category_id": v.get("category_id"),
            "duration_seconds": v.get("duration_seconds"),
            "thumbnails": v.get("thumbnails"),
            "stats": v.get("stats"),
            "status": v.get("status")
        })

    latency_ms = int((time.time() - start_t) * 1000)
    _update_request(req_id, status="succeeded", finished_at=now_iso, http_status=200,
                    youtube_units_charged=units, cache_hit=True,
                    response_payload={"count": len(items), "next_page_token": next_token, "latency_ms": latency_ms})
    _persist_client(client)

    return {
        "request_id": req_id,
        "data": {
            "region_code": region_code,
            "category_id": category_id,
            "items": items,
            "page_token": page_token,
            "next_page_token": next_token,
            "limit": lim,
            "total_cached_candidates": len(cands)
        }
    }

def get_video_enhanced_transcript(youtube_video_ids=None, video_ids=None, language=None, include_auto_generated=None, start_time_seconds=None, end_time_seconds=None, search_query=None, segment_size_seconds=None, format=None, include_video_metadata=None, refresh=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0248000" if __import__("os").path.isdir("./environment_mix/0248000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return _iso(now)

    def _parse_dt(x):
        if x is None:
            return None
        if isinstance(x, datetime.datetime):
            return x if x.tzinfo else x.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(x, str):
            return None
        s = x.strip()
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(s)
        except ValueError:
            return None
        return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)

    _B32 = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _gen_id(prefix):
        ms = int(time.time() * 1000)
        tpart = ms
        out = []
        for _ in range(10):
            out.append(_B32[tpart % 32]); tpart //= 32
        rnd = int.from_bytes(os.urandom(10), "big")
        for _ in range(16):
            out.append(_B32[rnd % 32]); rnd //= 32
        return prefix + "".join(reversed(out))

    def _next_reset_boundary(dt):
        dt = dt.astimezone(datetime.timezone.utc)
        d = dt.date() + datetime.timedelta(days=1)
        return datetime.datetime(d.year, d.month, d.day, tzinfo=datetime.timezone.utc)

    def _truncate_payload(obj, limit=50000):
        try:
            s = json.dumps(obj, ensure_ascii=False)
        except Exception:
            return {"note": "non-serializable payload"}
        if len(s) <= limit:
            return obj
        return {"truncated": True, "chars": len(s), "preview": s[:limit]}

    def _pick_client_for_call():
        # Ambient auth: pick ANY active client that can serve a request now (quota+status).
        clients = _load("api_clients.json")
        if isinstance(clients, dict) and "rows" in clients:
            clients = clients["rows"]
        if not isinstance(clients, list):
            clients = []
        # Reset quota if needed, then pick first that can serve.
        changed = False
        for c in clients:
            if not isinstance(c, dict):
                continue
            if c.get("status") != "active":
                continue
            qr = _parse_dt(c.get("quota_reset_at"))
            if qr is None:
                # Repair a bad row to be usable
                c["quota_reset_at"] = _iso(_next_reset_boundary(now))
                c["requests_used_today"] = int(c.get("requests_used_today") or 0)
                c["youtube_units_used_today"] = int(c.get("youtube_units_used_today") or 0)
                c["updated_at"] = _iso(now)
                changed = True
            else:
                if qr <= now:
                    c["requests_used_today"] = 0
                    c["youtube_units_used_today"] = 0
                    c["quota_reset_at"] = _iso(_next_reset_boundary(now))
                    c["updated_at"] = _iso(now)
                    changed = True
        if changed:
            _save("api_clients.json", clients)
        # Choose client with remaining quota
        for c in clients:
            if not isinstance(c, dict):
                continue
            if c.get("status") != "active":
                continue
            try:
                qreq = int(c.get("quota_daily_requests"))
                qunits = int(c.get("quota_daily_youtube_units"))
                used_req = int(c.get("requests_used_today") or 0)
                used_units = int(c.get("youtube_units_used_today") or 0)
            except Exception:
                continue
            # This tool charges a small amount; use 1 unit baseline.
            charge = 1
            if qreq >= 0 and qunits >= 0 and (used_req + 1) <= qreq and (used_units + charge) <= qunits:
                return c, charge
        return None, 1

    # -------- validate inputs (relaxed: do not enforce vendor regex too strictly) --------
    if youtube_video_ids is None and video_ids is None:
        # Must still create tool_request row per rules; do that after we pick a client.
        pass

    if youtube_video_ids is not None and not (isinstance(youtube_video_ids, list) and len(youtube_video_ids) >= 1 and all(isinstance(x, str) and x.strip() for x in youtube_video_ids)):
        # log later; return validation error
        youtube_video_ids = "__INVALID__"
    if video_ids is not None and not (isinstance(video_ids, list) and len(video_ids) >= 1 and all(isinstance(x, str) and x.strip() for x in video_ids)):
        video_ids = "__INVALID__"

    if language is not None and not (isinstance(language, str) and 2 <= len(language.strip()) <= 15):
        return _err("VALIDATION_ERROR", "language must be a string length 2..15")
    if include_auto_generated is not None and not isinstance(include_auto_generated, bool):
        return _err("VALIDATION_ERROR", "include_auto_generated must be boolean")
    if include_video_metadata is not None and not isinstance(include_video_metadata, bool):
        return _err("VALIDATION_ERROR", "include_video_metadata must be boolean")
    if refresh is not None and not isinstance(refresh, bool):
        return _err("VALIDATION_ERROR", "refresh must be boolean")
    if start_time_seconds is not None and not (isinstance(start_time_seconds, (int, float)) and start_time_seconds >= 0):
        return _err("VALIDATION_ERROR", "start_time_seconds must be a non-negative number")
    if end_time_seconds is not None and not (isinstance(end_time_seconds, (int, float)) and end_time_seconds >= 0):
        return _err("VALIDATION_ERROR", "end_time_seconds must be a non-negative number")
    if start_time_seconds is not None and end_time_seconds is not None and end_time_seconds < start_time_seconds:
        return _err("VALIDATION_ERROR", "end_time_seconds must be >= start_time_seconds")
    if search_query is not None and not isinstance(search_query, str):
        return _err("VALIDATION_ERROR", "search_query must be a string")
    if segment_size_seconds is not None and not (isinstance(segment_size_seconds, (int, float)) and segment_size_seconds >= 1):
        return _err("VALIDATION_ERROR", "segment_size_seconds must be a number >= 1")
    if format is None:
        format = "detailed"
    if not (isinstance(format, str) and format in ("text", "segments", "detailed")):
        return _err("VALIDATION_ERROR", "format must be one of: text, segments, detailed")

    # -------- pick an authenticated/authorized context (ambient) and create tool_request --------
    client, units_charge = _pick_client_for_call()
    tool_requests = _load("tool_requests.json")
    if isinstance(tool_requests, dict) and "rows" in tool_requests:
        tool_requests = tool_requests["rows"]
    if not isinstance(tool_requests, list):
        tool_requests = []

    req_id = _gen_id("ytb_req_")
    base_req = {
        "id": req_id,
        "client_id": client["id"] if client else None,
        "tool_name": "get_video_enhanced_transcript",
        "input_params": _truncate_payload({
            "youtube_video_ids": youtube_video_ids,
            "video_ids": video_ids,
            "language": language,
            "include_auto_generated": include_auto_generated,
            "start_time_seconds": start_time_seconds,
            "end_time_seconds": end_time_seconds,
            "search_query": search_query,
            "segment_size_seconds": segment_size_seconds,
            "format": format,
            "include_video_metadata": include_video_metadata,
            "refresh": refresh
        }),
        "normalized_query": None,
        "region_code": None,
        "youtube_video_id": None,
        "youtube_channel_id": None,
        "resolved_video_id": None,
        "resolved_channel_id": None,
        "response_payload": None,
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "youtube_units_charged": int(units_charge),
        "cache_hit": False,
        "status": "received",
        "started_at": None,
        "finished_at": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    tool_requests.append(base_req)
    _save("tool_requests.json", tool_requests)

    def _finalize(req_row, status, http_status=None, error_code=None, error_message=None, response_payload=None, cache_hit=False):
        req_row["status"] = status
        req_row["http_status"] = http_status
        req_row["error_code"] = error_code
        req_row["error_message"] = error_message
        req_row["response_payload"] = _truncate_payload(response_payload) if response_payload is not None else None
        req_row["cache_hit"] = bool(cache_hit)
        req_row["finished_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        req_row["updated_at"] = req_row["finished_at"]
        _save("tool_requests.json", tool_requests)

    if client is None:
        # No active+quota-capable client exists anywhere -> unauthorized for ambient auth calls.
        _finalize(base_req, "failed", http_status=401, error_code="UNAUTHORIZED", error_message="No active client with sufficient quota is available to serve this request.")
        return _err("UNAUTHORIZED", "No active client with sufficient quota is available to serve this request.")

    # Client inactive rule (should not happen due to picker, but enforce)
    if client.get("status") != "active":
        _finalize(base_req, "failed", http_status=403, error_code="CLIENT_INACTIVE", error_message="Client is not active.")
        return _err("UNAUTHORIZED", "Client is not active.", error_code="CLIENT_INACTIVE")

    # quota enforcement (requests + youtube units)
    try:
        used_req = int(client.get("requests_used_today") or 0)
        used_units = int(client.get("youtube_units_used_today") or 0)
        qreq = int(client.get("quota_daily_requests"))
        qunits = int(client.get("quota_daily_youtube_units"))
    except Exception:
        _finalize(base_req, "failed", http_status=500, error_code="SERVER_STATE_INVALID", error_message="Client quota fields invalid.")
        return _err("CONFLICT", "Client quota fields invalid.")

    if (used_req + 1) > qreq:
        _finalize(base_req, "failed", http_status=429, error_code="QUOTA_DAILY_REQUESTS", error_message="Daily request quota exceeded.")
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.")
    if (used_units + units_charge) > qunits:
        _finalize(base_req, "failed", http_status=429, error_code="QUOTA_DAILY_YOUTUBE_UNITS", error_message="Daily YouTube units quota exceeded.")
        return _err("QUOTA_EXCEEDED", "Daily YouTube units quota exceeded.")

    # Transition to running
    base_req["status"] = "running"
    base_req["started_at"] = _iso(now)
    base_req["updated_at"] = _iso(now)
    _save("tool_requests.json", tool_requests)

    # increment client counters now that it's accepted
    clients_all = _load("api_clients.json")
    if isinstance(clients_all, dict) and "rows" in clients_all:
        clients_all = clients_all["rows"]
    if not isinstance(clients_all, list):
        clients_all = []
    for c in clients_all:
        if isinstance(c, dict) and c.get("id") == client.get("id"):
            c["requests_used_today"] = int(c.get("requests_used_today") or 0) + 1
            c["youtube_units_used_today"] = int(c.get("youtube_units_used_today") or 0) + int(units_charge)
            c["updated_at"] = _iso(now)
            client = c
            break
    _save("api_clients.json", clients_all)

    # validate oneOf after logging (business rule: invalid args recorded failed w/400)
    if youtube_video_ids is None and video_ids is None:
        _finalize(base_req, "failed", http_status=400, error_code="INVALID_ARGUMENT", error_message="Either youtube_video_ids or video_ids is required.")
        return _err("VALIDATION_ERROR", "Either youtube_video_ids or video_ids is required.")
    if youtube_video_ids == "__INVALID__":
        _finalize(base_req, "failed", http_status=400, error_code="INVALID_ARGUMENT", error_message="youtube_video_ids must be a non-empty array of strings.")
        return _err("VALIDATION_ERROR", "youtube_video_ids must be a non-empty array of strings.")
    if video_ids == "__INVALID__":
        _finalize(base_req, "failed", http_status=400, error_code="INVALID_ARGUMENT", error_message="video_ids must be a non-empty array of strings.")
        return _err("VALIDATION_ERROR", "video_ids must be a non-empty array of strings.")

    # -------- resolve videos and transcripts from cache --------
    videos = _load("videos.json")
    if isinstance(videos, dict) and "rows" in videos:
        videos = videos["rows"]
    if not isinstance(videos, list):
        videos = []
    channels = _load("channels.json")
    if isinstance(channels, dict) and "rows" in channels:
        channels = channels["rows"]
    if not isinstance(channels, list):
        channels = []
    vtas = _load("video_text_assets.json")
    if isinstance(vtas, dict) and "rows" in vtas:
        vtas = vtas["rows"]
    if not isinstance(vtas, list):
        vtas = []

    videos_by_id = {v.get("id"): v for v in videos if isinstance(v, dict) and v.get("id")}
    videos_by_yid = {v.get("youtube_video_id"): v for v in videos if isinstance(v, dict) and v.get("youtube_video_id")}

    def _match_language(asset_lang):
        if language is None:
            return True
        if not isinstance(asset_lang, str):
            return False
        want = language.strip().lower()
        have = asset_lang.strip().lower()
        # prefix match: "en" matches "en-us"
        return have == want or have.startswith(want + "-") or want.startswith(have + "-")

    def _pick_transcript_asset(video_row):
        if not video_row:
            return None
        vid = video_row.get("id")
        if not vid:
            return None
        candidates = []
        for a in vtas:
            if not isinstance(a, dict):
                continue
            if a.get("video_id") != vid:
                continue
            if a.get("asset_type") != "transcript":
                continue
            if a.get("status") not in ("available", "stale"):
                continue
            if not _match_language(a.get("language")) and language is not None:
                continue
            if include_auto_generated is False and a.get("is_auto_generated") is True:
                continue
            candidates.append(a)
        if not candidates:
            return None
        # prefer available over stale; prefer exact language match; prefer non-auto-generated
        def _score(a):
            s = 0
            if a.get("status") == "available":
                s += 10
            if language is not None and isinstance(a.get("language"), str):
                want = language.strip().lower()
                have = a.get("language").strip().lower()
                if have == want:
                    s += 5
                elif have.startswith(want + "-"):
                    s += 3
            if a.get("is_auto_generated") is False:
                s += 2
            # newer last_fetched_at
            dt = _parse_dt(a.get("last_fetched_at"))
            if dt:
                s += min(5, int((dt.timestamp() % 100000) / 20000))
            return s
        candidates.sort(key=_score, reverse=True)
        return candidates[0]

    def _segments_from_asset(asset):
        segs = asset.get("segments")
        if isinstance(segs, list) and segs:
            out = []
            for s in segs:
                if not isinstance(s, dict):
                    continue
                st = s.get("start_ms")
                en = s.get("end_ms")
                txt = s.get("text")
                if not isinstance(st, (int, float)) or not isinstance(en, (int, float)) or not isinstance(txt, str):
                    continue
                out.append({"start_ms": int(st), "end_ms": int(en), "text": txt, **({} if "confidence" not in s else {"confidence": s.get("confidence")})})
            if out:
                return out
        # fall back to splitting full text into a single segment if present
        txt = asset.get("text")
        if isinstance(txt, str) and txt.strip():
            return [{"start_ms": 0, "end_ms": 0, "text": txt.strip()}]
        return []

    def _apply_filters(segments):
        segs = list(segments)
        if start_time_seconds is not None:
            start_ms = int(float(start_time_seconds) * 1000.0)
            segs = [s for s in segs if isinstance(s, dict) and int(s.get("end_ms") or 0) >= start_ms]
        if end_time_seconds is not None:
            end_ms = int(float(end_time_seconds) * 1000.0)
            segs = [s for s in segs if isinstance(s, dict) and int(s.get("start_ms") or 0) <= end_ms]
        if start_time_seconds is not None or end_time_seconds is not None:
            start_ms = int(float(start_time_seconds) * 1000.0) if start_time_seconds is not None else None
            end_ms = int(float(end_time_seconds) * 1000.0) if end_time_seconds is not None else None
            # clamp boundaries
            clamped = []
            for s in segs:
                st = int(s.get("start_ms") or 0)
                en = int(s.get("end_ms") or 0)
                txt = s.get("text") if isinstance(s.get("text"), str) else ""
                if start_ms is not None and st < start_ms:
                    st = start_ms
                if end_ms is not None and en > end_ms:
                    en = end_ms
                clamped.append({**s, "start_ms": st, "end_ms": en, "text": txt})
            segs = clamped
        if search_query is not None and search_query.strip():
            q = search_query.strip().lower()
            segs = [s for s in segs if isinstance(s.get("text"), str) and q in s["text"].lower()]
        return segs

    def _group_segments(segments):
        if not segment_size_seconds:
            return segments
        bucket_ms = int(float(segment_size_seconds) * 1000.0)
        if bucket_ms <= 0:
            return segments
        grouped = []
        current = None
        for s in segments:
            st = int(s.get("start_ms") or 0)
            en = int(s.get("end_ms") or st)
            txt = s.get("text") if isinstance(s.get("text"), str) else ""
            if current is None:
                current = {"start_ms": st, "end_ms": en, "text": txt}
                continue
            if (en - current["start_ms"]) <= bucket_ms:
                current["end_ms"] = max(current["end_ms"], en)
                if txt:
                    current["text"] = (current["text"] + " " + txt).strip() if current["text"] else txt
            else:
                grouped.append(current)
                current = {"start_ms": st, "end_ms": en, "text": txt}
        if current is not None:
            grouped.append(current)
        return grouped

    def _video_metadata(vrow):
        if not include_video_metadata:
            return None
        if not vrow:
            return None
        meta = {k: vrow.get(k) for k in ("id", "youtube_video_id", "channel_id", "title", "description", "published_at", "duration_seconds", "category_id", "default_language", "tags", "thumbnails", "stats", "region_restriction", "last_fetched_at", "etag", "status", "created_at", "updated_at")}
        ch = None
        cid = vrow.get("channel_id")
        if cid:
            for c in channels:
                if isinstance(c, dict) and c.get("id") == cid:
                    ch = c
                    break
        if ch:
            meta["channel"] = {k: ch.get(k) for k in ("id", "youtube_channel_id", "handle", "title", "country", "published_at", "thumbnails", "stats", "last_fetched_at", "etag", "status", "created_at", "updated_at")}
        return meta

    targets = []
    if youtube_video_ids is not None:
        for yid in youtube_video_ids:
            vrow = videos_by_yid.get(yid)
            targets.append(("youtube_video_id", yid, vrow))
    if video_ids is not None:
        for vid in video_ids:
            vrow = videos_by_id.get(vid)
            targets.append(("video_id", vid, vrow))

    results = []
    any_cache_hit = True
    videos_touched = False
    vtas_touched = False

    for kind, key, vrow in targets:
        entry = {
            "input": {kind: key},
            "video_id": vrow.get("id") if vrow else None,
            "youtube_video_id": vrow.get("youtube_video_id") if vrow else (key if kind == "youtube_video_id" else None),
            "status": None,
            "language": None,
            "is_auto_generated": None,
            "source": None,
            "last_fetched_at": None,
            "format": format,
            "data": None,
            "video_metadata": None,
            "error": None,
        }

        # refresh behavior: simulate re-extraction by bumping last_fetched_at and making stale->available if possible.
        asset = _pick_transcript_asset(vrow) if vrow else None

        if refresh and vrow:
            # Find any transcript asset for the video (even unavailable/stale) and "refresh" it.
            candidates = [a for a in vtas if isinstance(a, dict) and a.get("video_id") == vrow.get("id") and a.get("asset_type") == "transcript"]
            if candidates:
                # pick best existing candidate and update timestamps + status
                chosen = candidates[0]
                for a in candidates[1:]:
                    # prefer non-tombstoned
                    if chosen.get("status") == "tombstoned" and a.get("status") != "tombstoned":
                        chosen = a
                chosen["last_fetched_at"] = _iso(now)
                if chosen.get("status") in ("stale",):
                    chosen["status"] = "available"
                chosen["updated_at"] = _iso(now)
                vtas_touched = True
                asset = _pick_transcript_asset(vrow)
            else:
                # create a placeholder unavailable transcript asset so future calls see the attempt
                new_asset = {
                    "id": _gen_id("ytb_txt_"),
                    "video_id": vrow.get("id"),
                    "asset_type": "transcript",
                    "youtube_asset_id": None,
                    "language": language if isinstance(language, str) else None,
                    "is_auto_generated": True if include_auto_generated else None,
                    "author_channel_youtube_id": None,
                    "author_display_name": None,
                    "like_count": None,
                    "published_at": None,
                    "segments": [],
                    "text": None,
                    "source": "unknown",
                    "last_fetched_at": _iso(now),
                    "status": "unavailable",
                    "created_at": _iso(now),
                    "updated_at": _iso(now),
                }
                vtas.append(new_asset)
                vtas_touched = True
                asset = None

        if not vrow:
            any_cache_hit = False
            entry["status"] = "not_found"
            entry["error"] = {"code": "NOT_FOUND", "message": "Video not found in cache."}
            results.append(entry)
            continue

        # do not serve tombstoned/unavailable videos metadata as successful transcript
        if vrow.get("status") in ("tombstoned", "unavailable"):
            any_cache_hit = True
            entry["status"] = "unavailable"
            entry["error"] = {"code": "UPSTREAM_NOT_FOUND", "message": "Video is marked unavailable/tombstoned in cache."}
            results.append(entry)
            continue

        if not asset:
            any_cache_hit = False
            entry["status"] = "transcript_unavailable"
            entry["error"] = {"code": "UPSTREAM_NOT_FOUND", "message": "Transcript asset not available in cache."}
            results.append(entry)
            continue

        segs = _segments_from_asset(asset)
        segs = _apply_filters(segs)
        segs = _group_segments(segs)

        entry["status"] = "ok"
        entry["language"] = asset.get("language")
        entry["is_auto_generated"] = asset.get("is_auto_generated")
        entry["source"] = asset.get("source")
        entry["last_fetched_at"] = asset.get("last_fetched_at")

        if include_video_metadata:
            entry["video_metadata"] = _video_metadata(vrow)

        if format == "text":
            entry["data"] = "\n".join([s.get("text", "") for s in segs if isinstance(s.get("text"), str) and s.get("text")])
        elif format == "segments":
            entry["data"] = [{"start_ms": s.get("start_ms"), "end_ms": s.get("end_ms"), "text": s.get("text")} for s in segs]
        else:  # detailed
            entry["data"] = {
                "segments": segs,
                "segment_count": len(segs),
                "filters": {
                    "start_time_seconds": start_time_seconds,
                    "end_time_seconds": end_time_seconds,
                    "search_query": search_query,
                    "segment_size_seconds": segment_size_seconds,
                },
            }
        results.append(entry)

    if vtas_touched:
        _save("video_text_assets.json", vtas)

    resp = {
        "request_id": req_id,
        "client_id": client.get("id"),
        "youtube_units_charged": int(units_charge),
        "results": results,
        "count": len(results),
    }

    _finalize(base_req, "succeeded", http_status=200, response_payload=resp, cache_hit=bool(any_cache_hit))

    # latency recorded in response payload for observability (also persisted via tool_requests response_payload)
    resp["latency_ms"] = int((time.time() - t0) * 1000)
    resp["cache_hit"] = bool(any_cache_hit)
    return resp

def create_api_client(name, quota_daily_requests=None, quota_daily_youtube_units=None, enforce_unique_name=None, **_extra):
    import json, os, datetime, time, hashlib, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0248000" if __import__("os").path.isdir("./environment_mix/0248000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    if not isinstance(name, str) or len(name.strip()) < 1 or len(name.strip()) > 120:
        return _err("VALIDATION_ERROR", "name must be a non-empty string of length 1..120")
    name = name.strip()

    if quota_daily_requests is None:
        quota_daily_requests = 10000
    if quota_daily_youtube_units is None:
        quota_daily_youtube_units = 100000
    if enforce_unique_name is None:
        enforce_unique_name = False

    if not isinstance(quota_daily_requests, int) or quota_daily_requests < 0 or quota_daily_requests > 1000000:
        return _err("VALIDATION_ERROR", "quota_daily_requests must be an integer between 0 and 1000000")
    if not isinstance(quota_daily_youtube_units, int) or quota_daily_youtube_units < 0 or quota_daily_youtube_units > 10000000:
        return _err("VALIDATION_ERROR", "quota_daily_youtube_units must be an integer between 0 and 10000000")
    if not isinstance(enforce_unique_name, bool):
        return _err("VALIDATION_ERROR", "enforce_unique_name must be a boolean")

    clients = _load("api_clients.json")
    tool_reqs = _load("tool_requests.json")

    if enforce_unique_name:
        for c in clients:
            if isinstance(c, dict) and c.get("name") == name and c.get("status") != "deleted":
                return _err("CONFLICT", "Client name already in use")

    def _next_midnight_utc(dt):
        dt = dt.astimezone(datetime.timezone.utc)
        d = dt.date()
        return datetime.datetime(d.year, d.month, d.day, tzinfo=datetime.timezone.utc) + datetime.timedelta(days=1)

    alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"

    def _gen_ulid_like(prefix):
        return prefix + "".join(secrets.choice(alphabet) for _ in range(26))

    def _hash_key(k):
        return hashlib.sha256(k.encode("utf-8")).hexdigest()

    def _iso(dt):
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    # generate unique api_key (plaintext shown once) and store hash unique
    for _ in range(20):
        api_key_plain = "ytb_key_" + secrets.token_urlsafe(32)
        api_key_hash = _hash_key(api_key_plain)
        if not any(isinstance(c, dict) and c.get("api_key_hash") == api_key_hash for c in clients):
            break
    else:
        return _err("CONFLICT", "Could not allocate unique api_key")

    client_id = _gen_ulid_like("ytb_cli_")
    created = _iso(now)
    client_row = {
        "id": client_id,
        "name": name,
        "api_key_hash": api_key_hash,
        "status": "active",
        "quota_daily_requests": quota_daily_requests,
        "quota_daily_youtube_units": quota_daily_youtube_units,
        "quota_reset_at": _iso(_next_midnight_utc(now)),
        "requests_used_today": 0,
        "youtube_units_used_today": 0,
        "created_at": created,
        "updated_at": created,
    }
    clients.append(client_row)
    _save("api_clients.json", clients)

    # Log this admin-ish operation as a tool_request for the created client (best-effort observability)
    tr = {
        "id": _gen_ulid_like("ytb_req_"),
        "client_id": client_id,
        "tool_name": "get_me",  # closest available in enum; schema lacks create_api_client
        "input_params": {
            "name": name,
            "quota_daily_requests": quota_daily_requests,
            "quota_daily_youtube_units": quota_daily_youtube_units,
            "enforce_unique_name": enforce_unique_name,
        },
        "normalized_query": None,
        "region_code": None,
        "youtube_video_id": None,
        "youtube_channel_id": None,
        "resolved_video_id": None,
        "resolved_channel_id": None,
        "response_payload": {"created_client_id": client_id},
        "http_status": 201,
        "error_code": None,
        "error_message": None,
        "youtube_units_charged": 0,
        "cache_hit": True,
        "status": "succeeded",
        "started_at": created,
        "finished_at": created,
        "created_at": created,
        "updated_at": created,
    }
    tool_reqs.append(tr)
    _save("tool_requests.json", tool_reqs)

    return {
        "api_client": client_row,
        "api_key": api_key_plain,
        "meta": {"latency_ms": int((time.time() - t0) * 1000)},
    }

def list_tool_requests(api_key, status=None, tool_name=None, youtube_video_id=None, youtube_channel_id=None, created_after=None, created_before=None, limit=None, page_token=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0248000" if __import__("os").path.isdir("./environment_mix/0248000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str): return dt
        if dt.tzinfo is None: dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(x):
        if x is None: return None
        if isinstance(x, datetime.datetime):
            return x if x.tzinfo else x.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(x, str): return None
        s = x.strip()
        if s.endswith("Z"): s = s[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(s)
        except ValueError:
            return None
        return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)

    _B32 = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _gen_id(prefix):
        ms = int(time.time() * 1000)
        tpart = ms
        out = []
        for _ in range(10):
            out.append(_B32[tpart % 32]); tpart //= 32
        rnd = int.from_bytes(os.urandom(10), "big")
        for _ in range(16):
            out.append(_B32[rnd % 32]); rnd //= 32
        return prefix + "".join(reversed(out))

    def _next_reset_boundary(dt):
        dt = dt.astimezone(datetime.timezone.utc)
        d = dt.date() + datetime.timedelta(days=1)
        return datetime.datetime(d.year, d.month, d.day, tzinfo=datetime.timezone.utc)

    def _truncate_payload(obj, limit=50000):
        try:
            s = json.dumps(obj, ensure_ascii=False)
        except Exception:
            return {"note": "non-serializable payload"}
        if len(s) <= limit:
            return obj
        return {"truncated": True, "chars": len(s), "preview": s[:limit]}

    # Validate
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if status is not None and status not in ("received", "running", "succeeded", "failed", "cancelled"):
        return _err("VALIDATION_ERROR", "status must be one of: received, running, succeeded, failed, cancelled")
    if tool_name is not None and not isinstance(tool_name, str):
        return _err("VALIDATION_ERROR", "tool_name must be a string")
    if youtube_video_id is not None and not isinstance(youtube_video_id, str):
        return _err("VALIDATION_ERROR", "youtube_video_id must be a string")
    if youtube_channel_id is not None and not isinstance(youtube_channel_id, str):
        return _err("VALIDATION_ERROR", "youtube_channel_id must be a string")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")
    if page_token is not None and (not isinstance(page_token, str) or not page_token.strip()):
        return _err("VALIDATION_ERROR", "page_token must be a non-empty string")

    created_after_dt = _parse_dt(created_after) if created_after is not None else None
    if created_after is not None and created_after_dt is None:
        return _err("VALIDATION_ERROR", "created_after must be an ISO date-time string")
    created_before_dt = _parse_dt(created_before) if created_before is not None else None
    if created_before is not None and created_before_dt is None:
        return _err("VALIDATION_ERROR", "created_before must be an ISO date-time string")

    clients = _load("api_clients.json")
    tool_requests = _load("tool_requests.json")

    # Authenticate by matching api_key to stored api_key_hash or id
    key = api_key.strip()
    client = next((c for c in clients if c.get("api_key_hash") == key or c.get("id") == key), None)

    # Log invocation (even unauthorized)
    req_id = _gen_id("ytb_req_")
    log_row = {
        "id": req_id,
        "client_id": client.get("id") if client else None,
        "tool_name": "list_tool_requests",
        "input_params": {"api_key": "***", "status": status, "tool_name": tool_name, "youtube_video_id": youtube_video_id,
                         "youtube_channel_id": youtube_channel_id, "created_after": created_after, "created_before": created_before,
                         "limit": limit, "page_token": page_token},
        "normalized_query": None,
        "region_code": None,
        "youtube_video_id": youtube_video_id,
        "youtube_channel_id": youtube_channel_id,
        "resolved_video_id": None,
        "resolved_channel_id": None,
        "response_payload": None,
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "youtube_units_charged": 0,
        "cache_hit": True,
        "status": "received",
        "started_at": _iso(now),
        "finished_at": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    tool_requests.append(log_row)
    log_row["status"] = "running"
    log_row["updated_at"] = _iso(now)

    if client is None:
        log_row["status"] = "failed"
        log_row["finished_at"] = _iso(now)
        log_row["http_status"] = 401
        log_row["error_code"] = "UNAUTHORIZED"
        log_row["error_message"] = "Invalid API key"
        log_row["updated_at"] = _iso(now)
        _save("tool_requests.json", tool_requests)
        return _err("UNAUTHORIZED", "Invalid API key")

    # Quota reset + enforce request quota
    qra = _parse_dt(client.get("quota_reset_at")) or now
    if qra <= now:
        client["requests_used_today"] = 0
        client["youtube_units_used_today"] = 0
        client["quota_reset_at"] = _iso(_next_reset_boundary(now))

    if client.get("status") != "active":
        log_row["status"] = "failed"
        log_row["finished_at"] = _iso(now)
        log_row["http_status"] = 403
        log_row["error_code"] = "CLIENT_INACTIVE"
        log_row["error_message"] = "Client is not active"
        log_row["updated_at"] = _iso(now)
        _save("tool_requests.json", tool_requests)
        _save("api_clients.json", clients)
        return _err("UNAUTHORIZED", "Client inactive", error_code="CLIENT_INACTIVE")

    ru = client.get("requests_used_today")
    qdr = client.get("quota_daily_requests")
    if not isinstance(ru, int) or ru < 0: ru = 0
    if not isinstance(qdr, int) or qdr < 0:
        log_row["status"] = "failed"
        log_row["finished_at"] = _iso(now)
        log_row["http_status"] = 400
        log_row["error_code"] = "VALIDATION_ERROR"
        log_row["error_message"] = "Client quota configuration invalid"
        log_row["updated_at"] = _iso(now)
        _save("tool_requests.json", tool_requests)
        return _err("VALIDATION_ERROR", "Client quota configuration invalid")

    if ru + 1 > qdr:
        log_row["status"] = "failed"
        log_row["finished_at"] = _iso(now)
        log_row["http_status"] = 429
        log_row["error_code"] = "QUOTA_EXCEEDED"
        log_row["error_message"] = "Daily request quota exceeded"
        log_row["updated_at"] = _iso(now)
        _save("tool_requests.json", tool_requests)
        _save("api_clients.json", clients)
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded", quota="quota_daily_requests")

    client["requests_used_today"] = ru + 1
    client["updated_at"] = _iso(now)
    _save("api_clients.json", clients)

    # Pagination token = base64("idx:<offset>")
    offset = 0
    if page_token:
        try:
            raw = base64.urlsafe_b64decode(page_token.encode("utf-8") + b"===")
            tok = raw.decode("utf-8")
            if tok.startswith("idx:"):
                offset = int(tok.split(":", 1)[1])
        except Exception:
            log_row["status"] = "failed"
            log_row["finished_at"] = _iso(now)
            log_row["http_status"] = 400
            log_row["error_code"] = "INVALID_ARGUMENT"
            log_row["error_message"] = "Invalid page_token"
            log_row["updated_at"] = _iso(now)
            _save("tool_requests.json", tool_requests)
            return _err("VALIDATION_ERROR", "Invalid page_token")

    # Filter by client_id (scope)
    rows = [r for r in tool_requests if r.get("client_id") == client.get("id")]

    if status is not None:
        rows = [r for r in rows if r.get("status") == status]
    if tool_name is not None:
        rows = [r for r in rows if r.get("tool_name") == tool_name]
    if youtube_video_id is not None:
        rows = [r for r in rows if r.get("youtube_video_id") == youtube_video_id]
    if youtube_channel_id is not None:
        rows = [r for r in rows if r.get("youtube_channel_id") == youtube_channel_id]
    if created_after_dt is not None:
        rows = [r for r in rows if (_parse_dt(r.get("created_at")) or now) >= created_after_dt]
    if created_before_dt is not None:
        rows = [r for r in rows if (_parse_dt(r.get("created_at")) or now) <= created_before_dt]

    # Newest-first default by created_at
    rows.sort(key=lambda r: (_parse_dt(r.get("created_at")) or now), reverse=True)

    page = rows[offset:offset + limit]
    next_offset = offset + limit
    next_page_token = None
    if next_offset < len(rows):
        next_page_token = base64.urlsafe_b64encode(("idx:%d" % next_offset).encode("utf-8")).decode("utf-8").rstrip("=")

    out = {"tool_requests": page, "next_page_token": next_page_token, "total": len(rows)}

    log_row["status"] = "succeeded"
    log_row["finished_at"] = _iso(now)
    log_row["http_status"] = 200
    log_row["response_payload"] = _truncate_payload({"returned": len(page), "total": len(rows), "next_page_token": next_page_token})
    log_row["updated_at"] = _iso(now)
    _save("tool_requests.json", tool_requests)

    return out

def cancel_tool_request(api_key, id, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0248000" if __import__("os").path.isdir("./environment_mix/0248000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if not isinstance(dt, datetime.datetime):
            dt = now
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(x):
        if x is None:
            return None
        if isinstance(x, datetime.datetime):
            return x if x.tzinfo else x.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(x, str):
            return None
        s = x.strip()
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(s)
        except ValueError:
            return None
        return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)

    def _next_reset_boundary(dt):
        dt = dt.astimezone(datetime.timezone.utc)
        d = dt.date() + datetime.timedelta(days=1)
        return datetime.datetime(d.year, d.month, d.day, tzinfo=datetime.timezone.utc)

    def _load_rows(payload):
        if isinstance(payload, dict) and "rows" in payload and isinstance(payload.get("rows"), list):
            return payload["rows"], payload
        if isinstance(payload, list):
            return payload, None
        return [], None

    def _persist_rows(filename, container, rows):
        if container is None:
            _save(filename, rows)
        else:
            container["rows"] = rows
            _save(filename, container)

    def _make_id(prefix):
        # ULID-like (Crockford base32) enough for pattern check
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(time.time() * 1000)
        v = ms
        chars = []
        for _ in range(10):
            chars.append(alphabet[v % 32])
            v //= 32
        # pad with some time-based variability
        while len(chars) < 12:
            ms = (ms * 1103515245 + 12345) & 0x7fffffff
            chars.append(alphabet[ms % 32])
        return prefix + "".join(reversed(chars))

    def _log_request(rows, container, rec):
        rows.append(rec)
        _persist_rows("tool_requests.json", container, rows)

    # --- Validate inputs ---
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key is required")
    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "id is required")
    if not re.match(r"^ytb_req_[0-9A-HJKMNP-TV-Z]{10,}$", id):
        return _err("VALIDATION_ERROR", "id must match pattern ^ytb_req_[0-9A-HJKMNP-TV-Z]{10,}$", id=id)

    # --- Authenticate via client-visible credential: accept api_clients.id OR api_clients.api_key_hash ---
    api_clients_payload = _load("api_clients.json")
    api_clients, api_clients_container = _load_rows(api_clients_payload)
    client = None
    for c in api_clients:
        if c.get("id") == api_key or c.get("api_key_hash") == api_key:
            client = c
            break
    if client is None:
        # No log possible without a client_id reference
        return _err("UNAUTHORIZED", "Invalid api_key")

    # --- Load tool_requests and find request (must belong to client) ---
    tr_payload = _load("tool_requests.json")
    tr_rows, tr_container = _load_rows(tr_payload)
    req = None
    for r in tr_rows:
        if r.get("id") == id:
            req = r
            break

    # Prepare a log row for this tool invocation (business rule: every invocation must be logged)
    log_id = _make_id("ytb_req_")
    started_at = now
    finished_at = now

    def _finalize_log(status, http_status=None, error_code=None, error_message=None, response_payload=None):
        rec = {
            "id": log_id,
            "client_id": client.get("id"),
            "tool_name": "cancel_tool_request",  # not in enum; still store for auditing forward-compatibility
            "input_params": {"api_key": api_key, "id": id},
            "normalized_query": None,
            "region_code": None,
            "youtube_video_id": None,
            "youtube_channel_id": None,
            "resolved_video_id": None,
            "resolved_channel_id": None,
            "response_payload": response_payload,
            "http_status": http_status,
            "error_code": error_code,
            "error_message": error_message,
            "youtube_units_charged": 0,
            "cache_hit": True,
            "status": status,
            "started_at": _iso(started_at),
            "finished_at": _iso(finished_at),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        # Ensure lifecycle path: received -> running -> terminal
        rec["status"] = "received"
        _log_request(tr_rows, tr_container, rec)
        rec["status"] = "running"
        rec["updated_at"] = _iso(now)
        _persist_rows("tool_requests.json", tr_container, tr_rows)
        rec["status"] = status
        rec["http_status"] = http_status
        rec["error_code"] = error_code
        rec["error_message"] = error_message
        rec["response_payload"] = response_payload
        rec["finished_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        rec["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        _persist_rows("tool_requests.json", tr_container, tr_rows)

    # Reject inactive client (but still logged)
    if client.get("status") != "active":
        _finalize_log(
            "failed",
            http_status=403,
            error_code="CLIENT_INACTIVE",
            error_message="Client is not active; tool invocations are rejected."
        )
        return _err("UNAUTHORIZED", "Client is not active", error_code="CLIENT_INACTIVE", client_id=client.get("id"))

    # Quota reset check + enforcement (requests only; this tool charges 0 youtube units)
    reset_at = _parse_dt(client.get("quota_reset_at"))
    if reset_at is not None and reset_at <= now:
        client["requests_used_today"] = 0
        client["youtube_units_used_today"] = 0
        client["quota_reset_at"] = _iso(_next_reset_boundary(now))
        client["updated_at"] = _iso(now)
        _persist_rows("api_clients.json", api_clients_container, api_clients)

    if not isinstance(client.get("requests_used_today"), int) or not isinstance(client.get("quota_daily_requests"), int):
        # datastore invariant violation; treat as validation-like failure
        _finalize_log("failed", http_status=500, error_code="INVALID_CLIENT_QUOTA", error_message="Client quota fields are invalid.")
        return _err("CONFLICT", "Client quota fields are invalid", client_id=client.get("id"))
    if client["requests_used_today"] + 1 > client["quota_daily_requests"]:
        _finalize_log("failed", http_status=429, error_code="QUOTA_DAILY_REQUESTS", error_message="Daily request quota exceeded.")
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded", quota="quota_daily_requests", client_id=client.get("id"))

    # Must exist and belong to client
    if req is None or req.get("client_id") != client.get("id"):
        _finalize_log("failed", http_status=404, error_code="NOT_FOUND", error_message="Tool request not found for this client.")
        # increment request counter despite failed call (still a request)
        client["requests_used_today"] += 1
        client["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        _persist_rows("api_clients.json", api_clients_container, api_clients)
        return _err("NOT_FOUND", "Tool request not found", id=id)

    # Cancel transition rules
    terminal = {"succeeded", "failed", "cancelled"}
    if req.get("status") in terminal:
        _finalize_log("failed", http_status=409, error_code="ALREADY_TERMINAL", error_message="Request already in a terminal state.")
        client["requests_used_today"] += 1
        client["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        _persist_rows("api_clients.json", api_clients_container, api_clients)
        return _err("CONFLICT", "Request is already in a terminal state", id=id, status=req.get("status"))

    if req.get("status") not in ("received", "running"):
        _finalize_log("failed", http_status=409, error_code="INVALID_TRANSITION", error_message="Only received|running can be cancelled.")
        client["requests_used_today"] += 1
        client["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        _persist_rows("api_clients.json", api_clients_container, api_clients)
        return _err("INVALID_TRANSITION", "Only received|running requests can be cancelled", from_status=req.get("status"), to_status="cancelled")

    # Perform transition and persist
    req["status"] = "cancelled"
    if req.get("started_at") is None:
        req["started_at"] = _iso(now)
    req["finished_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
    req["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
    _persist_rows("tool_requests.json", tr_container, tr_rows)

    # Charge request counter after successful mutation (still counts)
    client["requests_used_today"] += 1
    client["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
    _persist_rows("api_clients.json", api_clients_container, api_clients)

    _finalize_log("succeeded", http_status=200, response_payload={"cancelled_id": id})
    return {"tool_request": req, "meta": {"client_id": client.get("id"), "latency_ms": int((time.time() - t0) * 1000)}}

def set_cache_status(api_key, entity_type, id, status, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0248000" if __import__("os").path.isdir("./environment_mix/0248000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if not isinstance(dt, datetime.datetime):
            dt = now
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(x):
        if x is None:
            return None
        if isinstance(x, datetime.datetime):
            return x if x.tzinfo else x.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(x, str):
            return None
        s = x.strip()
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(s)
        except ValueError:
            return None
        return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)

    def _next_reset_boundary(dt):
        dt = dt.astimezone(datetime.timezone.utc)
        d = dt.date() + datetime.timedelta(days=1)
        return datetime.datetime(d.year, d.month, d.day, tzinfo=datetime.timezone.utc)

    def _load_rows(payload):
        if isinstance(payload, dict) and "rows" in payload and isinstance(payload.get("rows"), list):
            return payload["rows"], payload
        if isinstance(payload, list):
            return payload, None
        return [], None

    def _persist_rows(filename, container, rows):
        if container is None:
            _save(filename, rows)
        else:
            container["rows"] = rows
            _save(filename, container)

    def _make_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(time.time() * 1000)
        v = ms
        chars = []
        for _ in range(10):
            chars.append(alphabet[v % 32])
            v //= 32
        while len(chars) < 12:
            ms = (ms * 1103515245 + 12345) & 0x7fffffff
            chars.append(alphabet[ms % 32])
        return prefix + "".join(reversed(chars))

    # --- Validate inputs ---
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key is required")
    if entity_type not in ("channels", "videos", "video_text_assets"):
        return _err("VALIDATION_ERROR", "entity_type must be one of: channels, videos, video_text_assets", entity_type=entity_type)
    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "id is required")
    if not isinstance(status, str) or not status.strip():
        return _err("VALIDATION_ERROR", "status is required")

    # Entity lifecycles + transitions
    lifecycles = {
        "channels": {
            "values": ["active", "stale", "tombstoned"],
            "transitions": {"active": ["stale", "tombstoned"], "stale": ["active", "tombstoned"], "tombstoned": []},
            "file": "channels.json",
        },
        "videos": {
            "values": ["active", "stale", "unavailable", "tombstoned"],
            "transitions": {"active": ["stale", "unavailable", "tombstoned"], "stale": ["active", "unavailable", "tombstoned"], "unavailable": ["stale", "tombstoned"], "tombstoned": []},
            "file": "videos.json",
        },
        "video_text_assets": {
            "values": ["available", "stale", "unavailable", "tombstoned"],
            "transitions": {"available": ["stale", "unavailable", "tombstoned"], "stale": ["available", "unavailable", "tombstoned"], "unavailable": ["stale", "tombstoned"], "tombstoned": []},
            "file": "video_text_assets.json",
        },
    }
    lc = lifecycles[entity_type]
    if status not in lc["values"]:
        return _err(
            "VALIDATION_ERROR",
            "status is not valid for entity_type (lifecycle values mismatch). This violates the entity lifecycle enum.",
            entity_type=entity_type,
            status=status,
            allowed=lc["values"],
        )

    # --- Authenticate via client-visible credential: accept api_clients.id OR api_clients.api_key_hash ---
    api_clients_payload = _load("api_clients.json")
    api_clients, api_clients_container = _load_rows(api_clients_payload)
    client = None
    for c in api_clients:
        if c.get("id") == api_key or c.get("api_key_hash") == api_key:
            client = c
            break
    if client is None:
        return _err("UNAUTHORIZED", "Invalid api_key")

    # --- Log this invocation (tool_requests lifecycle) ---
    tr_payload = _load("tool_requests.json")
    tr_rows, tr_container = _load_rows(tr_payload)

    log_id = _make_id("ytb_req_")
    log_row = {
        "id": log_id,
        "client_id": client.get("id"),
        "tool_name": "set_cache_status",  # not in enum; store for audit
        "input_params": {"api_key": api_key, "entity_type": entity_type, "id": id, "status": status},
        "normalized_query": None,
        "region_code": None,
        "youtube_video_id": None,
        "youtube_channel_id": None,
        "resolved_video_id": None,
        "resolved_channel_id": None,
        "response_payload": None,
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "youtube_units_charged": 0,
        "cache_hit": True,
        "status": "received",
        "started_at": _iso(now),
        "finished_at": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    tr_rows.append(log_row)
    _persist_rows("tool_requests.json", tr_container, tr_rows)
    # received -> running
    log_row["status"] = "running"
    log_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
    _persist_rows("tool_requests.json", tr_container, tr_rows)

    def _finish_log(s, http_status=None, error_code=None, error_message=None, response_payload=None):
        log_row["status"] = s
        log_row["http_status"] = http_status
        log_row["error_code"] = error_code
        log_row["error_message"] = error_message
        log_row["response_payload"] = response_payload
        log_row["finished_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        log_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        _persist_rows("tool_requests.json", tr_container, tr_rows)

    # Reject inactive client
    if client.get("status") != "active":
        _finish_log("failed", http_status=403, error_code="CLIENT_INACTIVE", error_message="Client is not active; tool invocations are rejected.")
        return _err("UNAUTHORIZED", "Client is not active", error_code="CLIENT_INACTIVE", client_id=client.get("id"))

    # Quota reset check + enforcement (requests only; 0 youtube units)
    reset_at = _parse_dt(client.get("quota_reset_at"))
    if reset_at is not None and reset_at <= now:
        client["requests_used_today"] = 0
        client["youtube_units_used_today"] = 0
        client["quota_reset_at"] = _iso(_next_reset_boundary(now))
        client["updated_at"] = _iso(now)
        _persist_rows("api_clients.json", api_clients_container, api_clients)

    if not isinstance(client.get("requests_used_today"), int) or not isinstance(client.get("quota_daily_requests"), int):
        _finish_log("failed", http_status=500, error_code="INVALID_CLIENT_QUOTA", error_message="Client quota fields are invalid.")
        return _err("CONFLICT", "Client quota fields are invalid", client_id=client.get("id"))

    if client["requests_used_today"] + 1 > client["quota_daily_requests"]:
        _finish_log("failed", http_status=429, error_code="QUOTA_DAILY_REQUESTS", error_message="Daily request quota exceeded.")
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded", quota="quota_daily_requests", client_id=client.get("id"))

    # --- Load entity collection and locate row ---
    ent_payload = _load(lc["file"])
    ent_rows, ent_container = _load_rows(ent_payload)
    entity = None
    for r in ent_rows:
        if r.get("id") == id:
            entity = r
            break
    if entity is None:
        _finish_log("failed", http_status=404, error_code="NOT_FOUND", error_message="Entity not found.")
        client["requests_used_today"] += 1
        client["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        _persist_rows("api_clients.json", api_clients_container, api_clients)
        return _err("NOT_FOUND", "Entity not found", entity_type=entity_type, id=id)

    # --- Validate transition ---
    from_status = entity.get("status")
    if from_status not in lc["values"]:
        _finish_log("failed", http_status=409, error_code="INVALID_ENTITY_STATE", error_message="Entity has an unknown status; cannot transition safely.")
        client["requests_used_today"] += 1
        client["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        _persist_rows("api_clients.json", api_clients_container, api_clients)
        return _err("CONFLICT", "Entity has an unknown status; cannot transition", entity_type=entity_type, id=id, from_status=from_status)

    if status == from_status:
        # Idempotent: treat as success but still a counted request
        client["requests_used_today"] += 1
        client["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        _persist_rows("api_clients.json", api_clients_container, api_clients)
        _finish_log("succeeded", http_status=200, response_payload={"id": id, "entity_type": entity_type, "status": status, "idempotent": True})
        return {"entity_type": entity_type, "entity": entity, "meta": {"idempotent": True, "client_id": client.get("id"), "latency_ms": int((time.time() - t0) * 1000)}}

    allowed = lc["transitions"].get(from_status, [])
    if status not in allowed:
        _finish_log(
            "failed",
            http_status=400,
            error_code="INVALID_TRANSITION",
            error_message="Requested lifecycle transition is not allowed by entity transition rules.",
        )
        client["requests_used_today"] += 1
        client["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        _persist_rows("api_clients.json", api_clients_container, api_clients)
        return _err(
            "VALIDATION_ERROR",
            "Requested lifecycle transition is not allowed for this entity type/status (entity lifecycle transitions rule).",
            entity_type=entity_type,
            id=id,
            from_status=from_status,
            to_status=status,
            allowed_to=allowed,
        )

    # --- Mutate and persist ---
    entity["status"] = status
    entity["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
    # For caches/assets, forcing a status is a "touch": update last_fetched_at if present to now
    if "last_fetched_at" in entity:
        entity["last_fetched_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
    _persist_rows(lc["file"], ent_container, ent_rows)

    client["requests_used_today"] += 1
    client["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
    _persist_rows("api_clients.json", api_clients_container, api_clients)

    _finish_log("succeeded", http_status=200, response_payload={"id": id, "entity_type": entity_type, "from_status": from_status, "to_status": status})
    return {"entity_type": entity_type, "entity": entity, "meta": {"client_id": client.get("id"), "latency_ms": int((time.time() - t0) * 1000)}}
